use std::io::{Read, Write};

#[derive(Default, Clone)]
pub struct Options {
    pub output: Option<String>,
    pub format: String,
    pub static_: bool,
    pub embed_font: bool,
    pub check: bool,
    pub json: bool,
    pub theme: Option<String>,
    pub no_fs: bool,
    pub no_warn: bool,
    pub strict: bool,
    pub watch: bool,
}

fn read_input(path: &str) -> Result<String, String> {
    if path == "-" {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).map_err(|e| format!("error: failed to read stdin: {}", e))?;
        return Ok(s);
    }
    match std::fs::read(path) {
        Ok(b) => String::from_utf8(b).map_err(|_| format!("error: {}: stream did not contain valid UTF-8", path)),
        Err(e) => Err(format!("error: {}: {}", path, e)),
    }
}

pub fn compile_src(src: &str, file: &str, opts: &Options) -> Result<(String, Vec<diag::Diag>), (diag::Diag, Vec<diag::Diag>)> {
    let (doc, _comments) = parser::parse(src).map_err(|e| (e, vec![]))?;
    let sheet = scene::build_sheet(&doc).map_err(|e| (e, vec![]))?;
    let root = compile::root_decls_node(&sheet);
    let mut b = scene::Builder::new(&sheet, src);
    b.add(root, None);
    b.build_stmts(&doc.stmts, 0).map_err(|e| (e, vec![]))?;
    icon::validate(&b.nodes, b.sheet, file, opts).map_err(|e| (e, vec![]))?;
    b.resolve_links().map_err(|e| (e, vec![]))?;
    page::root_fixup(&mut b.nodes, b.sheet);
    b.unworn_class_warnings();
    let nodes = std::mem::take(&mut b.nodes);
    let links = std::mem::take(&mut b.links);
    let mut warnings = std::mem::take(&mut b.warnings);
    drop(b);
    let mut ctx = compile::Ctx {
        src: src.to_string(),
        file: file.to_string(),
        sheet,
        nodes,
        comp: vec![],
        links,
        warnings: std::mem::take(&mut warnings),
        root_font_size: 15.0,
        sk: Default::default(),
        link_geo: vec![],
    };
    compile::compute(&mut ctx);
    if drawing::expand(&mut ctx).map_err(|e| (e, vec![]))? {
        compile::compute(&mut ctx);
    }
    chart::validate(&ctx).map_err(|e| (e, vec![]))?;
    page::scale_units(&mut ctx);
    drawing::prepare(&mut ctx);
    ctx.root_font_size = ctx.comp[0].font_size;
    image::check_sizes(&ctx).map_err(|e| (e, vec![]))?;
    layout::measure(&mut ctx, 0, None);
    drawing::size_warnings(&mut ctx);
    links::compute(&mut ctx);
    let svg = render::render(&ctx, opts).map_err(|e| (e, vec![]))?;
    table::check_grids(&ctx).map_err(|e| (e, vec![]))?;
    Ok((svg, ctx.warnings))
}

fn write_out(opts: &Options, text: &str) {
    match &opts.output {
        Some(path) if path != "-" => {
            let _ = std::fs::write(path, text.as_bytes());
        }
        _ => {
            let mut so = std::io::stdout();
            let _ = so.write_all(text.as_bytes());
        }
    }
}

fn html_wrap(svg: &str) -> String {
    format!(
        "<!doctype html>\n<html>\n<head>\n  <meta charset=\"utf-8\">\n  <title>lini</title>\n</head>\n<body>\n{}</body>\n</html>\n",
        svg
    )
}

fn run_compile(input: &str, opts: &Options) -> i32 {
    if opts.format != "svg" && opts.format != "html" {
        eprintln!("error: invalid --format '{}' (expected svg|html)", opts.format);
        return 3;
    }
    if let Some(t) = &opts.theme {
        if theme::resolve(t).is_none() {
            eprintln!(
                "error: theme '{}': not a built-in (try: default, light, dark, high-contrast, blueprint), and reading it as a file failed: No such file or directory (os error 2)",
                t
            );
            return 2;
        }
    }
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let result = compile_src(&src, &file, opts);
    if opts.json {
        let (diags, failed) = match &result {
            Ok((_, w)) => (w.clone(), false),
            Err((e, w)) => {
                let mut d = w.clone();
                d.push(e.clone());
                (d, true)
            }
        };
        print!("{}", diag::render_json(&file, &src, &diags));
        if failed || (opts.strict && !diags.is_empty()) {
            return 1;
        }
        return 0;
    }
    match result {
        Ok((svg, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            if !opts.check {
                let text = if opts.format == "html" { html_wrap(&svg) } else { svg };
                write_out(opts, &text);
            }
            if opts.strict && !warns.is_empty() {
                return 1;
            }
            0
        }
        Err((e, warns)) => {
            if !opts.no_warn {
                for w in &warns {
                    eprintln!("{}", diag::render_text(&file, &src, w));
                }
            }
            eprintln!("{}", diag::render_text(&file, &src, &e));
            1
        }
    }
}

fn run_fmt(input: &str, check: bool, stdout: bool) -> i32 {
    let src = match read_input(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            return 2;
        }
    };
    let file = if input == "-" { "<stdin>".to_string() } else { input.to_string() };
    let out = match format::format(&src) {
        Ok(o) => o,
        Err(e) => {
            eprintln!("{}", diag::render_text(&file, &src, &e));
            return 1;
        }
    };
    if check {
        if out != src {
            eprintln!("{}: would reformat", file);
            return 1;
        }
        return 0;
    }
    if stdout || input == "-" {
        print!("{}", out);
        return 0;
    }
    if out != src {
        let _ = std::fs::write(input, out.as_bytes());
    }
    0
}

fn run_theme(name: &Option<String>) -> i32 {
    match name {
        None => {
            print!("{}", theme::LIST);
            0
        }
        Some(n) => match theme::css_of(n) {
            Some(css) => {
                print!("{}", css);
                0
            }
            None => {
                eprintln!("error: unknown theme '{}' (try one of: default, light, dark, high-contrast, blueprint)", n);
                3
            }
        },
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let code = match cli::parse(&args) {
        cli::Outcome::Print(s) => {
            print!("{}", s);
            0
        }
        cli::Outcome::Fail(s) => {
            eprint!("{}", s);
            3
        }
        cli::Outcome::Run(p) => match &p.cmd {
            cli::Cmd::Compile { input } => run_compile(input, &p.opts),
            cli::Cmd::Theme { name } => run_theme(name),
            cli::Cmd::Highlight { input: _, css: true } => {
                print!("{}", cli::HIGHLIGHT_CSS);
                0
            }
            cli::Cmd::Highlight { input: Some(input), css: false } => match read_input(input) {
                Ok(src) => {
                    print!("{}", highlight::highlight(&src));
                    0
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            cli::Cmd::Fmt { input, check, stdout } => run_fmt(input, *check, *stdout),
            cli::Cmd::Desugar { input } => match read_input(input) {
                Ok(src) => {
                    let file = if input == "-" { "<stdin>".to_string() } else { input.clone() };
                    match desugar::desugar(&src) {
                        Ok(out) => {
                            print!("{}", out);
                            0
                        }
                        Err(e) => {
                            eprintln!("{}", diag::render_text(&file, &src, &e));
                            1
                        }
                    }
                }
                Err(e) => {
                    eprintln!("{}", e);
                    2
                }
            },
            _ => 0,
        },
    };
    let _ = std::io::stdout().flush();
    std::process::exit(code);
}

// Built-in themes: the palette as `--lini-*` custom properties.

use std::collections::HashMap;

pub static DEFAULT_CSS: &str = include_str!("../data/themes/default.css");
pub static LIGHT_CSS: &str = include_str!("../data/themes/light.css");
pub static DARK_CSS: &str = include_str!("../data/themes/dark.css");
pub static HC_CSS: &str = include_str!("../data/themes/high-contrast.css");
pub static BLUEPRINT_CSS: &str = include_str!("../data/themes/blueprint.css");
pub static LIST: &str = include_str!("../data/themes/list.txt");

pub const FONT_FAMILY: &str =
    "\"Google Sans\", system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif";

pub const NAMES: &[&str] = &["default", "light", "dark", "high-contrast", "blueprint"];

pub fn css_of(name: &str) -> Option<&'static str> {
    match name {
        "default" => Some(DEFAULT_CSS),
        "light" => Some(LIGHT_CSS),
        "dark" => Some(DARK_CSS),
        "high-contrast" => Some(HC_CSS),
        "blueprint" => Some(BLUEPRINT_CSS),
        _ => None,
    }
}

// Split "light-dark(a, b)" at its top-level comma.
pub fn split_light_dark(v: &str) -> Option<(String, String)> {
    let inner = v.strip_prefix("light-dark(")?.strip_suffix(')')?;
    let mut depth = 0;
    for (i, c) in inner.char_indices() {
        match c {
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => {
                return Some((inner[..i].trim().to_string(), inner[i + 1..].trim().to_string()));
            }
            _ => {}
        }
    }
    None
}

#[derive(Clone, Debug)]
pub struct Theme {
    pub pair: bool,
    // var name (without --lini-) → (light, dark)
    pub vars: HashMap<String, (String, String)>,
}

pub fn parse_theme_css(css: &str) -> HashMap<String, (String, String)> {
    let mut m = HashMap::new();
    for line in css.lines() {
        let l = line.trim();
        if let Some(rest) = l.strip_prefix("--lini-") {
            if let Some(colon) = rest.find(':') {
                let name = rest[..colon].to_string();
                let val = rest[colon + 1..].trim().trim_end_matches(';').trim().to_string();
                let pair = split_light_dark(&val).unwrap_or((val.clone(), val.clone()));
                m.insert(name, pair);
            }
        }
    }
    m.insert("font-family".to_string(), (FONT_FAMILY.to_string(), FONT_FAMILY.to_string()));
    m
}

pub fn builtin(name: &str) -> Option<Theme> {
    let css = css_of(name)?;
    let pair = name == "default" || name == "high-contrast";
    Some(Theme { pair, vars: parse_theme_css(css) })
}

pub fn resolve(spec: &str) -> Option<Theme> {
    if let Some((a, b)) = spec.split_once('/') {
        let ta = builtin(a)?;
        let tb = builtin(b)?;
        let mut vars = HashMap::new();
        for (k, (l, _)) in &ta.vars {
            let d = tb.vars.get(k).map(|x| x.1.clone()).unwrap_or_else(|| l.clone());
            vars.insert(k.clone(), (l.clone(), d));
        }
        return Some(Theme { pair: true, vars });
    }
    builtin(spec)
}

impl Theme {
    pub fn css_value(&self, var: &str) -> Option<String> {
        let (l, d) = self.vars.get(var)?;
        if !self.pair || l == d {
            if !self.pair {
                return Some(l.clone());
            }
            return Some(l.clone());
        }
        Some(format!("light-dark({}, {})", l, d))
    }
    // the light-side literal value (for --static baking)
    pub fn light_value(&self, var: &str) -> Option<String> {
        self.vars.get(var).map(|x| x.0.clone())
    }
}
// Small shared helpers: number formatting, escaping, hashing.

// Numbers print with at most four decimals, trailing zeros trimmed.
pub fn f4(v: f64) -> String {
    let mut s = format!("{:.4}", v);
    if s.contains('.') {
        while s.ends_with('0') {
            s.pop();
        }
        if s.ends_with('.') {
            s.pop();
        }
    }
    if s == "-0" {
        s = "0".to_string();
    }
    s
}

// Rust's default float Display (shortest round-trip), used by a few raw paths.
pub fn fraw(v: f64) -> String {
    if v == 0.0 {
        return "0".to_string();
    }
    format!("{}", v)
}

pub fn xml_escape(s: &str) -> String {
    let mut o = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => o.push_str("&amp;"),
            '<' => o.push_str("&lt;"),
            '>' => o.push_str("&gt;"),
            '"' => o.push_str("&quot;"),
            '\'' => o.push_str("&apos;"),
            _ => o.push(c),
        }
    }
    o
}

pub fn fnv1a64(data: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &b in data {
        h ^= b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

pub fn fold32(h: u64) -> u32 {
    ((h >> 32) as u32) ^ (h as u32)
}

pub fn hash8(s: &str) -> String {
    format!("{:08x}", fold32(fnv1a64(s.as_bytes())))
}

// Levenshtein distance for "did you mean" suggestions.
pub fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

pub fn base64(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut o = String::with_capacity((data.len() + 2) / 3 * 4);
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        o.push(T[((n >> 18) & 63) as usize] as char);
        o.push(T[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            o.push(T[((n >> 6) & 63) as usize] as char);
        } else {
            o.push('=');
        }
        if chunk.len() > 2 {
            o.push(T[(n & 63) as usize] as char);
        } else {
            o.push('=');
        }
    }
    o
}
// Colour maths: OKLCH → sRGB hex.

pub fn oklch_to_srgb(l: f64, c: f64, h: f64) -> (f64, f64, f64) {
    let hr = h.to_radians();
    let a = c * hr.cos();
    let b = c * hr.sin();
    oklab_to_srgb(l, a, b)
}

pub fn oklab_to_srgb(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let l_ = l + 0.3963377774 * a + 0.2158037573 * b;
    let m_ = l - 0.1055613458 * a - 0.0638541728 * b;
    let s_ = l - 0.0894841775 * a - 1.2914855480 * b;
    let l3 = l_ * l_ * l_;
    let m3 = m_ * m_ * m_;
    let s3 = s_ * s_ * s_;
    let r = 4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3;
    let g = -1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3;
    let bb = -0.0041960863 * l3 - 0.7034186147 * m3 + 1.7076147010 * s3;
    (gamma(r), gamma(g), gamma(bb))
}

fn gamma(x: f64) -> f64 {
    if x <= 0.0031308 {
        12.92 * x
    } else {
        1.055 * x.powf(1.0 / 2.4) - 0.055
    }
}

pub fn to_byte(x: f64) -> u8 {
    (x.clamp(0.0, 1.0) * 255.0).round() as u8
}

pub fn oklch_hex(l: f64, c: f64, h: f64, alpha: Option<f64>) -> String {
    let (r, g, b) = oklch_to_srgb(l, c, h);
    match alpha {
        Some(a) if a < 1.0 => format!("#{:02x}{:02x}{:02x}{:02x}", to_byte(r), to_byte(g), to_byte(b), to_byte(a)),
        _ => format!("#{:02x}{:02x}{:02x}", to_byte(r), to_byte(g), to_byte(b)),
    }
}

