244	            // nested var() references pull their targets in too
245	            let mut rest = val.as_str();
246	            while let Some(p) = rest.find("var(--lini-") {
247	                let after = &rest[p + 11..];
248	                let end = after.find(')').unwrap_or(after.len());
249	                let name = after[..end].to_string();
250	                if !vars.contains(&name) {
251	                    vars.push(name);
252	                }
253	                rest = &after[end..];
254	            }
255	            decl_vars.push((v, val));
256	        }
257	    }
258	    decl_vars.sort_by(|a, b| a.0.cmp(&b.0));
259	    let mut css = String::new();
260	    css.push_str("    @layer lini.defaults {\n");
261	    let mut root_line = String::from("      :root, .lini {");
262	    if theme.pair {
263	        root_line.push_str(" color-scheme: light dark;");
264	    }
265	    for (k, v) in &decl_vars {
266	        root_line.push_str(&format!(" --lini-{}: {};", k, v));
267	    }
268	    root_line.push_str(" }\n");
269	    css.push_str(&root_line);
270	    if theme.pair {
271	        css.push_str("      .lini[data-theme=\"dark\"], [data-theme=\"dark\"] .lini { color-scheme: dark; }\n");
272	        css.push_str("      .lini[data-theme=\"light\"], [data-theme=\"light\"] .lini { color-scheme: light; }\n");
273	    }
274	    css.push_str("    }\n");
275	    css.push_str("    .lini, .lini text { font-family: var(--lini-font-family); }\n");
276	    css.push_str(&format!(
277	        "    .lini {{ font-size: {}px; font-weight: var(--lini-font-weight); color: var(--lini-text-color); }}\n",
278	        f4(ctx.root_font_size)
279	    ));
280	    for r in &rules {
281	        css.push_str(&format!("    .lini {}\n", r));
282	    }
283	    let hash = hash8(&css);
284	    let scope = format!("lini-scope-{}", hash);
285	    let css_scoped = scope_css(&css, &scope);
286	    // the frame
287	    let (vx, vy, vw, vh) = viewbox(ctx);
288	    // a bare sheet document states its paper size in mm
289	    let (sw, sh) = match crate::page::svg_mm(ctx) {
290	        Some(k) => (format!("{}mm", f4(vw / k)), format!("{}mm", f4(vh / k))),
291	        None => (f4(vw), f4(vh)),
292	    };
293	    let mut s = String::new();
294	    s.push_str(&format!(
295	        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"{} {} {} {}\" width=\"{}\" height=\"{}\" class=\"lini {}\">\n",
296	        f4(vx),
297	        f4(vy),
298	        f4(vw),
299	        f4(vh),
300	        sw,
301	        sh,
302	        scope
303	    ));
304	    s.push_str("  <style>\n");
305	    s.push_str(&css_scoped);
306	    s.push_str("  </style>\n");
307	    if out.defs.is_empty() {
308	        s.push_str("  <defs/>\n");
309	    } else {
310	        s.push_str("  <defs>\n");
311	        for d in &out.defs {
312	            s.push_str(&format!("    {}\n", d));
313	        }
314	        s.push_str("  </defs>\n");
315	    }
316	    if canvas_fill.is_some() {
317	        s.push_str(&format!(
318	            "  <rect class=\"lini-canvas\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"/>\n",
319	            f4(vx),
320	            f4(vy),
321	            f4(vw),
322	            f4(vh)
323	        ));
324	    }
325	    s.push_str("  <g class=\"lini-scene\">\n");
326	    s.push_str(&scene);
327	    s.push_str("  </g>\n");
328	    s.push_str(&links_layer);
329	    s.push_str("</svg>\n");
330	    Ok(s)
331	}
