333	fn scope_css(css: &str, scope: &str) -> String {
334	    // replace the '.lini' scope selector (not '.lini-xxx' classes)
335	    let mut o = String::new();
336	    let b = css.as_bytes();
337	    let mut i = 0;
338	    while i < b.len() {
339	        if css[i..].starts_with(".lini") {
340	            let next = b.get(i + 5).copied().unwrap_or(b' ');
341	            if next != b'-' {
342	                o.push('.');
343	                o.push_str(scope);
344	                i += 5;
345	                continue;
346	            }
347	        }
348	        let ch = css[i..].chars().next().unwrap();
349	        o.push(ch);
350	        i += ch.len_utf8();
351	    }
352	    o
353	}
