355	pub fn value_css_text(ctx: &Ctx, v: &Value, vars: &mut Vec<String>) -> String {
356	    let mut parts = Vec::new();
357	    for g in &v.groups {
358	        let mut gp = Vec::new();
359	        for t in g {
360	            match t {
361	                Term::Num(x, _, _) => gp.push(f4(*x)),
362	                Term::Var(n, _) => {
363	                    use_var(vars, n);
364	                    gp.push(format!("var(--lini-{})", n));
365	                }
366	                Term::Hash(h, _) => gp.push(format!("#{}", h)),
367	                Term::Ident(n, _) => gp.push(n.clone()),
368	                Term::Str(s, _) => gp.push(format!("\"{}\"", s)),
369	                _ => {
370	                    if let Ok(c) = color_css(t, vars, v.span) {
371	                        gp.push(c);
372	                    }
373	                }
374	            }
375	        }
376	        parts.push(gp.join(" "));
377	    }
378	    let _ = ctx;
379	    parts.join(", ")
380	}
