406	// affine [a b c d e f]: x' = a x + c y + e, y' = b x + d y + f
407	fn mul(m: &[f64; 6], n: &[f64; 6]) -> [f64; 6] {
408	    [
409	        m[0] * n[0] + m[2] * n[1],
410	        m[1] * n[0] + m[3] * n[1],
411	        m[0] * n[2] + m[2] * n[3],
412	        m[1] * n[2] + m[3] * n[3],
413	        m[0] * n[4] + m[2] * n[5] + m[4],
414	        m[1] * n[4] + m[3] * n[5] + m[5],
415	    ]
416	}
