418	pub fn node_matrix(ctx: &Ctx, i: usize) -> [f64; 6] {
419	    let n = &ctx.nodes[i];
420	    let c = &ctx.comp[i];
421	    let t = [1.0, 0.0, 0.0, 1.0, n.x + c.translate.0, n.y + c.translate.1];
422	    if c.rotate != 0.0 {
423	        let a = c.rotate.to_radians();
424	        let r = [a.cos(), a.sin(), -a.sin(), a.cos(), 0.0, 0.0];
425	        mul(&t, &r)
426	    } else {
427	        t
428	    }
429	}
