431	// The frame a node's group draws in: translate(position + geometry offset)
432	// then its rotation — what `render_node` writes as its transform.
433	pub fn group_matrix(ctx: &Ctx, i: usize) -> [f64; 6] {
434	    let n = &ctx.nodes[i];
435	    let c = &ctx.comp[i];
436	    let t = [1.0, 0.0, 0.0, 1.0, n.x + c.translate.0 + n.geo_off.0, n.y + c.translate.1 + n.geo_off.1];
437	    if c.rotate != 0.0 {
438	        let a = c.rotate.to_radians();
439	        let r = [a.cos(), a.sin(), -a.sin(), a.cos(), 0.0, 0.0];
440	        mul(&t, &r)
441	    } else {
442	        t
443	    }
444	}
