446	fn bbox_walk(ctx: &Ctx, i: usize, parent: &[f64; 6], b: &mut [f64; 4]) {
447	    let n = &ctx.nodes[i];
448	    let m = mul(parent, &group_matrix(ctx, i));
449	    let (ow, oh) = crate::layout::outer(ctx, i);
450	    let (cx, cy) = (-n.geo_off.0, -n.geo_off.1);
451	    let corners = if crate::drawing::skip_box(ctx, i) {
452	        vec![]
453	    } else {
454	        vec![(-ow / 2.0, -oh / 2.0), (ow / 2.0, -oh / 2.0), (ow / 2.0, oh / 2.0), (-ow / 2.0, oh / 2.0)]
455	    };
456	    for (px, py) in corners {
457	        let (px, py) = (px + cx, py + cy);
458	        let x = m[0] * px + m[2] * py + m[4];
459	        let y = m[1] * px + m[3] * py + m[5];
460	        b[0] = b[0].min(x);
461	        b[1] = b[1].min(y);
462	        b[2] = b[2].max(x);
463	        b[3] = b[3].max(y);
464	    }
465	    if let Some(cb) = crate::chart::content_bbox(i) {
466	        for (px, py) in [(cb[0], cb[1]), (cb[2], cb[1]), (cb[2], cb[3]), (cb[0], cb[3])] {
467	            if px.is_finite() && py.is_finite() {
468	                let x = m[0] * px + m[2] * py + m[4];
469	                let y = m[1] * px + m[3] * py + m[5];
470	                b[0] = b[0].min(x);
471	                b[1] = b[1].min(y);
472	                b[2] = b[2].max(x);
473	                b[3] = b[3].max(y);
474	            }
475	        }
476	        return;
477	    }
478	    if n.prim != Prim::Text {
479	        for &ch in &n.children {
480	            bbox_walk(ctx, ch, &m, b);
481	        }
482	    }
483	}
