485	pub fn paint_order(ctx: &Ctx, children: &[usize]) -> Vec<usize> {
486	    let mut flow: Vec<usize> = Vec::new();
487	    let mut pinned: Vec<usize> = Vec::new();
488	    for &c in children {
489	        if ctx.comp[c].pin.is_some() {
490	            pinned.push(c);
491	        } else {
492	            flow.push(c);
493	        }
494	    }
495	    flow.extend(pinned);
496	    flow
497	}
