517	// Inline CSS: the node's own declarations minus what its rules already say.
518	pub fn inline_style(ctx: &Ctx, i: usize, out: &mut Out, text: bool) -> Result<String, Diag> {
519	    let n = &ctx.nodes[i];
520	    let (mut rule_props, all) = crate::compile::cascade(&ctx.sheet, n);
521	    let mut own: Vec<(String, Value)> = Vec::new();
522	    // no `.lini-image` rule is emitted: the image type's own rules ride inline
523	    let sw_default = if n.prim == Prim::Image { crate::image::inline_type_rules(ctx, n, &mut own, &mut rule_props) } else { 2.0 };
524	    if let Some(id) = &n.id {
525	        for (rid, ds) in &ctx.sheet.id_rules {
526	            if rid == id {
527	                for d in ds {
528	                    own.retain(|e| e.0 != d.name);
529	                    own.push((d.name.clone(), d.value.clone()));
530	                }
531	            }
532	        }
533	    }
534	    for d in &n.inline {
535	        own.retain(|e| e.0 != d.name);
536	        own.push((d.name.clone(), d.value.clone()));
537	    }
538	    let sw_all = get(&all, "stroke-width").and_then(|w| value_num(&ctx.sheet.env, w)).unwrap_or(sw_default);
539	    let mut tmp = Vec::new();
540	    let own_d = css_decls(ctx, &own, &mut tmp, sw_all, text)?;
541	    let mut tmp2 = Vec::new();
542	    let sw_rule = get(&rule_props, "stroke-width").and_then(|w| value_num(&ctx.sheet.env, w)).unwrap_or(sw_default);
543	    let rule_d = css_decls(ctx, &rule_props, &mut tmp2, sw_rule, text)?;
544	    let mut keep = Vec::new();
545	    let mut own_d = own_d;
546	    if text {
547	        if let Some(fam) = &ctx.comp[i].family_css {
548	            if !own_d.iter().any(|(k, _)| k == "font-family") {
549	                own_d.push(("font-family".into(), fam.clone()));
550	                let pos = |k: &str| CSS_ORDER.iter().position(|x| *x == k || (*x == "stroke-style" && k == "stroke-dasharray") || (*x == "color" && k == "fill" && false)).unwrap_or(99);
551	                own_d.sort_by_key(|(k, _)| if k == "fill" { 0 } else { pos(k) });
552	            }
553	        }
554	    }
555	    for (k, v) in own_d {
556	        if rule_d.iter().any(|(rk, rv)| rk == &k && rv == &v) {
557	            continue;
558	        }
559	        keep.push((k, v));
560	    }
561	    // stroke-style depends on the effective stroke width
562	    if get(&own, "stroke-style").is_none() && get(&own, "stroke-width").is_some() {
563	        if let Some(st) = get(&all, "stroke-style").and_then(ident_of) {
564	            if st != "solid" {
565	                if let Some(d) = dasharray(st, sw_all) {
566	                    if !rule_d.iter().any(|(rk, rv)| rk == "stroke-dasharray" && rv == &d) {
567	                        keep.push(("stroke-dasharray".into(), d));
568	                    }
569	                }
570	            }
571	        }
572	    }
573	    // a font-scale resolves against the parent's size, the rule against the root's
574	    if !text && get(&own, "font-size").is_none() && get(&all, "font-size").is_none() {
575	        if let Some(rule_sz) = font_scale_size(ctx, &all) {
576	            let sz = ctx.comp[i].font_size;
577	            if (sz - rule_sz).abs() > 1e-9 {
578	                let pos = |k: &str| CSS_ORDER.iter().position(|x| *x == k || (*x == "stroke-style" && k == "stroke-dasharray")).unwrap_or(99);
579	                let at = keep.iter().position(|(k, _)| pos(k) > pos("font-size")).unwrap_or(keep.len());
580	                keep.insert(at, ("font-size".to_string(), format!("{}px", f4(sz))));
581	            }
582	        }
583	    }
584	    let mut vars = Vec::new();
585	    let _ = css_decls(ctx, &own, &mut vars, sw_all, text)?;
586	    for (k, _) in &keep {
587	        let _ = k;
588	    }
589	    for v in vars {
590	        // only vars that survive into the emitted style count
591	        if keep.iter().any(|(_, val)| val.contains(&format!("var(--lini-{})", v))) {
592	            use_var(&mut out.vars, &v);
593	        }
594	    }
595	    Ok(join_decls(&keep))
596	}
