598	fn render_text(ctx: &Ctx, i: usize, ind_n: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
599	    out.any_text = true;
600	    let n = &ctx.nodes[i];
601	    let c = &ctx.comp[i];
602	    let style = inline_style(ctx, i, out, true)?;
603	    let mut extra = String::new();
604	    let x = n.x + c.translate.0;
605	    let y = n.y + c.translate.1;
606	    let fam_attr = if let Some(v) = n.inline.iter().find(|d| d.name == "font-family") {
607	        Some(font_family_css(&v.value))
608	    } else {
609	        None
610	    };
611	    let _ = fam_attr;
612	    if !style.is_empty() {
613	        extra = format!(" style=\"{}\"", xml_escape(&style));
614	    }
615	    // worn classes ride the text element
616	    let mut tcls = String::from("lini-text");
617	    for k in &n.classes {
618	        tcls.push_str(&format!(" lini-style-{}", k));
619	        if !out.used_classes.contains(k) {
620	            out.used_classes.push(k.clone());
621	        }
622	    }
623	    let lines = &n.lines;
624	    let ls = c.letter_spacing;
625	    let dx_for = |l: &str| -> String {
626	        let cnt = l.chars().count();
627	        if ls != 0.0 && cnt > 1 {
628	            let mut v = vec!["0".to_string()];
629	            for _ in 1..cnt {
630	                v.push(f4(ls));
631	            }
632	            format!(" dx=\"{}\"", v.join(" "))
633	        } else {
634	            String::new()
635	        }
636	    };
637	    if lines.len() <= 1 {
638	        let l = lines.first().cloned().unwrap_or_default();
639	        s.push_str(&format!(
640	            "{}<text class=\"{}\" x=\"{}\" y=\"{}\" dy=\"0.358em\"{}{}>{}</text>\n",
641	            ind(ind_n),
642	            tcls,
643	            f4(x),
644	            f4(y),
645	            dx_for(&l),
646	            extra,
647	            xml_escape(&l)
648	        ));
649	    } else {
650	        let pitch = 1.2 * c.font_size + c.line_spacing;
651	        let total = (lines.len() as f64 - 1.0) * pitch;
652	        let first = y - total / 2.0 + 0.358 * c.font_size;
653	        let mut t = String::new();
654	        // lines flush by the holding box's horizontal knob
655	        let knob = crate::table::text_flush(ctx, i);
656	        for (k, l) in lines.iter().enumerate() {
657	            let slack = n.w - crate::layout::line_width(ctx, i, l);
658	            let lx = match knob {
659	                crate::compile::Align::Start => x - slack / 2.0,
660	                crate::compile::Align::End => x + slack / 2.0,
661	                _ => x,
662	            };
663	            if k == 0 {
664	                t.push_str(&format!("<tspan x=\"{}\" y=\"{}\"{}>{}</tspan>", f4(lx), f4(first), dx_for(l), xml_escape(l)));
665	            } else {
666	                t.push_str(&format!("<tspan x=\"{}\" dy=\"{}\"{}>{}</tspan>", f4(lx), f4(pitch), dx_for(l), xml_escape(l)));
667	            }
668	        }
669	        s.push_str(&format!("{}<text class=\"{}\" x=\"{}\" y=\"{}\"{}>{}</text>\n", ind(ind_n), tcls, f4(x), f4(y), extra, t));
670	    }
671	    Ok(())
672	}
