690	// The node's outline elements (unindented), centred on its origin.
691	pub fn shape_lines(ctx: &Ctx, i: usize) -> Vec<String> {
692	    let n = &ctx.nodes[i];
693	    let c = &ctx.comp[i];
694	    let (w, h) = (n.w, n.h);
695	    if let Some(v) = crate::drawing::shape_override(ctx, i) {
696	        return v;
697	    }
698	    let mut v = Vec::new();
699	    match n.prim {
700	        Prim::Block if w == 0.0 || h == 0.0 => {}
701	        Prim::Block => {
702	            v.push(format!(
703	                "<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" rx=\"{}\" ry=\"{}\"/>",
704	                f4(-w / 2.0),
705	                f4(-h / 2.0),
706	                f4(w),
707	                f4(h),
708	                f4(c.radius),
709	                f4(c.radius)
710	            ));
711	        }
712	        Prim::Oval => {
713	            v.push(format!("<ellipse cx=\"0\" cy=\"0\" rx=\"{}\" ry=\"{}\"/>", f4(w / 2.0), f4(h / 2.0)));
714	        }
715	        Prim::Hex => {
716	            v.push(format!(
717	                "<polygon points=\"{},0 {},{} {},{} {},0 {},{} {},{}\"/>",
718	                f4(-w / 2.0),
719	                f4(-w / 4.0),
720	                f4(-h / 2.0),
721	                f4(w / 4.0),
722	                f4(-h / 2.0),
723	                f4(w / 2.0),
724	                f4(w / 4.0),
725	                f4(h / 2.0),
726	                f4(-w / 4.0),
727	                f4(h / 2.0)
728	            ));
729	        }
730	        Prim::Diamond => {
731	            v.push(format!(
732	                "<polygon points=\"0,{} {},0 0,{} {},0\"/>",
733	                f4(-h / 2.0),
734	                f4(w / 2.0),
735	                f4(h / 2.0),
736	                f4(-w / 2.0)
737	            ));
738	        }
739	        Prim::Slant => {
740	            let skew = prop_nums(ctx, i, "skew").first().copied().unwrap_or(15.0);
741	            let off = (skew.to_radians()).tan() * h / 2.0;
742	            v.push(format!(
743	                "<polygon points=\"{},{} {},{} {},{} {},{}\"/>",
744	                f4(-w / 2.0 + off),
745	                f4(-h / 2.0),
