pub fn is_named_color(s: &str) -> bool {
    let l = s.to_ascii_lowercase();
    NAMED_COLORS.contains(&l.as_str())
}

pub fn valid_hex(h: &str) -> bool {
    matches!(h.len(), 3 | 4 | 6 | 8) && h.chars().all(|c| c.is_ascii_hexdigit())
}

// Serialise an expression argument of a colour function.
fn expr_text(e: &Expr) -> String {
    match e {
        Expr::Num(v, _) => f4(*v),
        Expr::Percent(v, _) => format!("{}%", f4(*v)),
        Expr::Ident(n, _) => n.clone(),
        Expr::Unary(op, a, _) => format!("{}{}", op, expr_text(a)),
        _ => String::new(),
    }
}

pub struct CssCtx<'a> {
    pub env: &'a Env,
    pub vars_used: &'a mut Vec<String>,
}

pub fn use_var(vars_used: &mut Vec<String>, name: &str) {
    if !vars_used.iter().any(|v| v == name) {
        vars_used.push(name.to_string());
    }
}

// A colour term → CSS text. Errors carry the declaration span.
pub fn color_css(t: &Term, vars_used: &mut Vec<String>, span: Span) -> Result<String, Diag> {
    match t {
        Term::Var(v, _) => {
            use_var(vars_used, v);
            Ok(format!("var(--lini-{})", v))
        }
        Term::Hash(h, sp) => {
            if !valid_hex(h) {
                return Err(Diag::error("parse", &format!("invalid hex color '#{}'", h), *sp));
            }
            Ok(format!("#{}", h))
        }
        Term::Ident(n, _) => {
            if is_named_color(n) {
                Ok(n.clone())
            } else {
                Err(Diag::error("invalid-color", &format!("invalid color '{}'", n), span))
            }
        }
        Term::Str(s, _) => Ok(format!("\"{}\"", s)),
        Term::Call(name, args, _) => match name.as_str() {
            "rgb" | "rgba" | "hsl" | "hsla" => {
                let parts: Vec<String> = args.iter().map(expr_text).collect();
                Ok(format!("{}({})", name, parts.join(", ")))
            }
            "oklch" => {
                let nums: Vec<f64> = args
                    .iter()
                    .map(|a| match a {
                        Expr::Num(v, _) => *v,
                        Expr::Unary(o, b, _) if o == "-" => match &**b {
                            Expr::Num(v, _) => -*v,
                            _ => f64::NAN,
                        },
                        _ => f64::NAN,
                    })
                    .collect();
                if (nums.len() != 3 && nums.len() != 4) || nums.iter().any(|x| x.is_nan()) {
                    return Err(Diag::error(
                        "malformed-value",
                        "oklch expects (L, C, H) or (L, C, H, A) — L and A in 0..1, C ≥ 0, H in degrees",
                        span,
                    ));
                }
                Ok(crate::color::oklch_hex(nums[0], nums[1], nums[2], nums.get(3).copied()))
            }
            _ => Err(Diag::error("invalid-color", &format!("invalid color '{}'", name), span)),
        },
        _ => Err(Diag::error("invalid-color", "invalid color", span)),
    }
}

pub fn weight_css(v: &Value, vars_used: &mut Vec<String>, span: Span) -> Result<String, Diag> {
    let bad = || {
        Diag::error(
            "malformed-value",
            "'font-weight' takes normal, medium, semibold, bold, or 400, 500, 600, 700",
            span,
        )
    };
    match single_term(v) {
        Some(Term::Ident(n, _)) => Ok(match n.as_str() {
            "normal" => "normal".into(),
            "bold" => "bold".into(),
            "medium" => "500".into(),
            "semibold" => "600".into(),
            "light" => "normal".into(),
            _ => return Err(bad()),
        }),
        Some(Term::Num(x, _, _)) => {
            if [400.0, 500.0, 600.0, 700.0].contains(x) {
                Ok(f4(*x))
            } else {
                Err(bad())
            }
        }
        Some(Term::Var(n, _)) => {
            use_var(vars_used, n);
            Ok(format!("var(--lini-{})", n))
        }
        _ => Err(bad()),
    }
}

// Numeric weight for metrics (vars resolve to their theme value).
pub fn weight_num(v: &Value) -> u32 {
    match single_term(v) {
        Some(Term::Ident(n, _)) => match n.as_str() {
            "bold" => 700,
            "semibold" => 600,
            "medium" => 500,
            _ => 400,
        },
        Some(Term::Num(x, _, _)) => *x as u32,
        Some(Term::Var(n, _)) => match n.as_str() {
            "caption-font-weight" | "link-font-weight" => 400,
            "font-weight" => 500,
            _ => 500,
        },
        _ => 500,
    }
}

pub fn dasharray(style: &str, sw: f64) -> Option<String> {
    match style {
        "solid" => Some("none".into()),
        "dashed" => Some(format!("{},{}", f4(2.0 * sw + 3.0), f4(1.5 * sw + 2.5))),
        "dotted" => Some(format!("{},{}", f4(sw), f4(1.5 * sw))),
        "center" => {
            let g = f4(1.5 * sw + 1.5);
            Some(format!("{},{},{},{}", f4(5.0 * sw + 5.0), g, f4(sw), g))
        }
        "phantom" => {
            let g = f4(1.5 * sw + 1.5);
            Some(format!("{},{},{},{},{},{}", f4(5.0 * sw + 5.0), g, f4(sw), g, f4(sw), g))
        }
        _ => None,
    }
}

pub fn text_shadow_css(env: &Env, v: &Value, vars_used: &mut Vec<String>, span: Span) -> Result<String, Diag> {
    let mut parts = Vec::new();
    for g in &v.groups {
        let mut gp = Vec::new();
        for t in g {
            match t {
                Term::Num(..) | Term::Group(..) => {
                    let x = term_num(env, t).unwrap_or(0.0);
                    gp.push(format!("{}px", f4(x)));
                }
                _ => gp.push(color_css(t, vars_used, span)?),
            }
        }
        parts.push(gp.join(" "));
    }
    Ok(parts.join(", "))
}

pub fn font_family_css(v: &Value) -> String {
    let mut parts = Vec::new();
    for g in &v.groups {
        let mut gp = Vec::new();
        for t in g {
            match t {
                Term::Str(s, _) => gp.push(format!("\"{}\"", s)),
                Term::Ident(s, _) => gp.push(s.clone()),
                _ => {}
            }
        }
        parts.push(gp.join(" "));
    }
    parts.join(", ")
}

pub fn family_of(v: &Value) -> crate::font::Family {
    let mut s = String::new();
    for g in &v.groups {
        for t in g {
            match t {
                Term::Str(x, _) | Term::Ident(x, _) => {
                    s = x.to_ascii_lowercase();
                }
                _ => {}
            }
        }
        break;
    }
    if s.contains("mono") || s.contains("code") || s == "monospace" {
        crate::font::Family::Code
    } else {
        crate::font::Family::Sans
    }
}
// Diagnostics: errors and warnings with stable codes and source spans.

#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn new(start: usize, end: usize) -> Span {
        Span { start, end }
    }
    pub fn to(self, other: Span) -> Span {
        Span { start: self.start.min(other.start), end: self.end.max(other.end) }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone)]
pub struct Diag {
    pub family: String,
    pub severity: Severity,
    pub message: String,
    pub span: Span,
    pub fixes: Vec<Fix>,
}

#[derive(Debug, Clone)]
pub struct Fix {
    pub message: String,
    pub span: Span,
    pub replacement: String,
}

impl Diag {
    pub fn error(family: &str, message: &str, span: Span) -> Diag {
        Diag { family: family.to_string(), severity: Severity::Error, message: message.to_string(), span, fixes: vec![] }
    }
    pub fn warning(family: &str, message: &str, span: Span) -> Diag {
        Diag { family: family.to_string(), severity: Severity::Warning, message: message.to_string(), span, fixes: vec![] }
    }
    pub fn code(&self) -> &'static str {
        family_code(&self.family)
    }
}

pub fn family_code(family: &str) -> &'static str {
    match family {
        "lex" => "L000",
        "unterminated-string" => "L001",
        "bad-escape" => "L002",
        "unexpected-char" => "L004",
        "parse" => "P000",
        "expected-token" => "P001",
        "empty-bars" => "P002",
        "invalid-id" => "P003",
        "declaration-outside-block" => "P004",
        "stylesheet-after-canvas" => "P005",
        "text-carries-children" => "P006",
        "spaced-call-paren" => "P007",
        "validate" => "V000",
        "unknown-property" => "V001",
        "class-never-worn" => "V004",
        "malformed-value" => "V005",
        "invalid-color" => "V010",
        "resolve" => "R000",
        "unknown-type" => "R001",
        "unknown-class" => "R002",
        "duplicate-id" => "R003",
        "unknown-endpoint" => "R008",
        "chain-too-short" => "R009",
        "asset-not-found" => "R010",
        "asset-no-fs" => "R024",
        "layout" => "Y000",
        "missing-required-property" => "Y001",
        "chart-data" => "Y002",
        "chart-type" => "Y009",
        "impossible-link" => "T001",
        "law-breach" => "T002",
        _ => "X000",
    }
}

// Line/column (1-based, columns counted in chars) of a byte offset.
pub fn line_col(src: &str, off: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for (i, c) in src.char_indices() {
        if i >= off {
            break;
        }
        if c == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

pub fn render_text(file: &str, src: &str, d: &Diag) -> String {
    let (l, c) = line_col(src, d.span.start);
    let sev = match d.severity {
        Severity::Error => "error",
        Severity::Warning => "warning",
    };
    format!("{}:{}:{}: {}: {}", file, l, c, sev, d.message)
}

pub fn json_escape(s: &str) -> String {
    let mut o = String::new();
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o
}

pub fn render_json(file: &str, src: &str, diags: &[Diag]) -> String {
    let mut o = String::new();
    o.push_str("{\n");
    o.push_str(&format!("  \"file\": \"{}\",\n", json_escape(file)));
    if diags.is_empty() {
        o.push_str("  \"diagnostics\": []\n}\n");
        return o;
    }
    o.push_str("  \"diagnostics\": [\n");
    for (i, d) in diags.iter().enumerate() {
        let (l, c) = line_col(src, d.span.start);
        let (el, ec) = line_col(src, d.span.end);
        let sev = match d.severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
        };
        o.push_str("    {\n");
        o.push_str(&format!("      \"code\": \"{}\",\n", d.code()));
        o.push_str(&format!("      \"family\": \"{}\",\n", json_escape(&d.family)));
        o.push_str(&format!("      \"severity\": \"{}\",\n", sev));
        o.push_str(&format!("      \"message\": \"{}\",\n", json_escape(&d.message)));
        o.push_str("      \"span\": {\n");
        o.push_str(&format!("        \"start\": {},\n", d.span.start));
        o.push_str(&format!("        \"end\": {},\n", d.span.end));
        o.push_str(&format!("        \"line\": {},\n", l));
        o.push_str(&format!("        \"col\": {},\n", c));
        o.push_str(&format!("        \"endLine\": {},\n", el));
        o.push_str(&format!("        \"endCol\": {}\n", ec));
        if d.fixes.is_empty() {
            o.push_str("      }\n");
        } else {
            o.push_str("      },\n");
            o.push_str("      \"fixes\": [\n");
            for (k, f) in d.fixes.iter().enumerate() {
                o.push_str("        {\n");
                o.push_str(&format!("          \"message\": \"{}\",\n", json_escape(&f.message)));
                o.push_str(&format!("          \"start\": {},\n", f.span.start));
                o.push_str(&format!("          \"end\": {},\n", f.span.end));
                o.push_str(&format!("          \"replacement\": \"{}\"\n", json_escape(&f.replacement)));
                o.push_str(if k + 1 < d.fixes.len() { "        },\n" } else { "        }\n" });
            }
            o.push_str("      ]\n");
        }
        o.push_str(if i + 1 < diags.len() { "    },\n" } else { "    }\n" });
    }
    o.push_str("  ]\n}\n");
    o
}

