pub struct Ctx {
    pub src: String,
    pub file: String,
    pub sheet: SheetModel,
    pub nodes: Vec<Node>,
    pub comp: Vec<Computed>,
    pub links: Vec<Link>,
    pub warnings: Vec<Diag>,
    pub root_font_size: f64,
    // sketch / drawing layout state (src/drawing.rs)
    pub sk: crate::drawing::State,
    // routed links (filled by links::compute after layout)
    pub link_geo: Vec<crate::links::LinkGeo>,
}

pub fn env(ctx: &Ctx) -> &Env {
    &ctx.sheet.env
}

// The cascade for one node: type chain (base first, defaults then user
// rules), classes, id rules, inline. Returns (rule-level props, all props).
pub fn cascade(sheet: &SheetModel, n: &Node) -> (Vec<(String, Value)>, Vec<(String, Value)>) {
    let mut props: Vec<(String, Value)> = Vec::new();
    fn set(props: &mut Vec<(String, Value)>, k: &str, v: &Value) {
        if let Some(e) = props.iter_mut().find(|e| e.0 == k) {
            e.1 = v.clone();
        } else {
            props.push((k.to_string(), v.clone()));
        }
    }
    // table column classes (.lini-align-*, .lini-justify-*) sit below every rule
    for t in n.chain.iter() {
        if let Some((k, v)) = crate::table::pseudo_class(t) {
            set(&mut props, k, &crate::table::pseudo_value(v));
        }
    }
    for t in n.chain.iter().rev() {
        for d in type_defaults(t) {
            set(&mut props, &d.name, &d.value);
        }
        if let Some(df) = sheet.define(t) {
            for d in &df.decls {
                set(&mut props, &d.name, &d.value);
            }
        }
        for d in sheet.type_rule(t) {
            set(&mut props, &d.name, &d.value);
        }
    }
    for c in &n.classes {
        if let Some(cr) = sheet.class(c) {
            for d in &cr.decls {
                set(&mut props, &d.name, &d.value);
            }
        }
    }
    let rule_level = props.clone();
    if let Some(id) = &n.id {
        for (rid, ds) in &sheet.id_rules {
            if rid == id {
                for d in ds {
                    set(&mut props, &d.name, &d.value);
                }
            }
        }
    }
    for d in &n.inline {
        set(&mut props, &d.name, &d.value);
    }
    (rule_level, props)
}

pub fn get<'a>(props: &'a [(String, Value)], k: &str) -> Option<&'a Value> {
    props.iter().find(|e| e.0 == k).map(|e| &e.1)
}

fn parse_align(s: &str) -> Option<Align> {
    match s {
        "start" | "top" | "left" => Some(Align::Start),
        "center" | "middle" => Some(Align::Center),
        "end" | "bottom" | "right" => Some(Align::End),
        "stretch" => Some(Align::Stretch),
        _ => None,
    }
}

pub fn compute(ctx: &mut Ctx) {
    let n = ctx.nodes.len();
    ctx.comp = vec![Computed::default(); n];
    // nodes are created parent-before-child, so a forward pass sees parents first
    for i in 0..n {
        let parent = ctx.nodes[i].parent;
        let pc = parent.map(|p| ctx.comp[p].clone());
        let (_, props) = if i == 0 { (vec![], ctx.nodes[0].inline.iter().map(|d| (d.name.clone(), d.value.clone())).collect()) } else { cascade(&ctx.sheet, &ctx.nodes[i]) };
        let env = &ctx.sheet.env;
        let mut c = Computed::default();
        if let Some(p) = &pc {
            c.font_size = p.font_size;
            c.font_weight = p.font_weight;
            c.family = p.family;
            c.letter_spacing = p.letter_spacing;
            c.line_spacing = p.line_spacing;
            c.text_transform = p.text_transform.clone();
            c.family_css = p.family_css.clone();
        }
        let num = |k: &str| get(&props, k).and_then(|v| value_num(env, v));
        if let Some(v) = num("font-size") {
            c.font_size = v;
        } else if let Some(v) = get(&props, "font-scale") {
            let xs = value_nums(env, v);
            if xs.len() == 2 {
                let base = pc.as_ref().map(|p| p.font_size).unwrap_or(15.0);
                c.font_size = xs[0] * base / xs[1];
            }
        }
        if let Some(v) = get(&props, "font-weight") {
            c.font_weight = weight_num(v);
        }
        if let Some(v) = get(&props, "font-family") {
            c.family = family_of(v);
            c.family_css = Some(font_family_css(v));
        }
        if let Some(v) = num("letter-spacing") {
            c.letter_spacing = v;
        }
        if let Some(v) = num("line-spacing") {
            c.line_spacing = v;
        }
        if let Some(v) = get(&props, "text-transform") {
            c.text_transform = ident_of(v).map(|s| s.to_string());
        }
        if let Some(v) = get(&props, "padding") {
            let xs = value_nums(env, v);
            c.padding = match xs.len() {
                1 => [xs[0]; 4],
                2 => [xs[0], xs[1], xs[0], xs[1]],
                4 => [xs[0], xs[1], xs[2], xs[3]],
                _ => [0.0; 4],
            };
        }
        if let Some(v) = get(&props, "gap") {
            let xs = value_nums(env, v);
            c.gap = match xs.len() {
                1 => (xs[0], xs[0]),
                2 => (xs[0], xs[1]),
                _ => c.gap,
            };
        }
        if let Some(v) = get(&props, "direction") {
            if ident_of(v) == Some("column") {
                c.direction = Dir::Column;
            }
        }
        if let Some(v) = get(&props, "align") {
            if let Some(a) = ident_of(v).and_then(parse_align) {
                c.align = a;
            }
        }
        if let Some(v) = get(&props, "justify") {
            if let Some(a) = ident_of(v).and_then(parse_align) {
                c.justify = a;
            }
        }
        c.width = num("width");
        c.height = num("height");
        c.max_width = num("max-width");
        if let Some(v) = num("stroke-width") {
            c.stroke_width = v;
        }
        if let Some(v) = get(&props, "stroke") {
            c.has_stroke = ident_of(v) != Some("none");
        }
        if let Some(v) = num("radius") {
            c.radius = v;
        }
        if let Some(v) = get(&props, "pin") {
            let mut parts = Vec::new();
            for g in &v.groups {
                for t in g {
                    if let Term::Ident(s, _) = t {
                        parts.push(s.clone());
                    }
                }
            }
            c.pin = Some(parts.join(" "));
        }
        if let Some(v) = get(&props, "translate") {
            let xs = value_nums(env, v);
            if xs.len() == 2 {
                c.translate = (xs[0], xs[1]);
            }
        }
        if let Some(v) = num("rotate") {
            c.rotate = v;
        }
        if let Some(v) = get(&props, "layout") {
            if let Some(s) = ident_of(v) {
                c.layout = s.to_string();
            }
        }
        if let Some(v) = get(&props, "text-wrap") {
            c.nowrap = ident_of(v) == Some("nowrap");
        }
        ctx.nodes[i].props = props.into_iter().collect();
        ctx.comp[i] = c;
    }
}

pub fn root_decls_node(sheet: &SheetModel) -> Node {
    let mut n = Node::new(Prim::Block, vec![], Span::default());
    let defaults = parse_decls("layout: flow; padding: 20; gap: 36; font-size: 15;");
    let mut inline = defaults;
    for d in &sheet.root {
        if let Some(e) = inline.iter_mut().find(|e| e.name == d.name) {
            *e = d.clone();
        } else {
            inline.push(d.clone());
        }
    }
    n.inline = inline;
    n
}
// Compile-time expression evaluation: bindings, functions, math.

use crate::ast::{Expr, Term};
use crate::diag::{Diag, Span};
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum EV {
    Num(f64),
    Tuple(Vec<EV>),
    Str(String),
}

impl EV {
    pub fn num(&self) -> Option<f64> {
        match self {
            EV::Num(v) => Some(*v),
            _ => None,
        }
    }
}

#[derive(Clone, Debug)]
pub struct Func {
    pub params: Vec<String>,
    pub body: Term,
}

#[derive(Default, Clone, Debug)]
pub struct Env {
    pub vars: HashMap<String, EV>,
    pub funcs: HashMap<String, Func>,
}

pub fn err(msg: &str, span: Span) -> Diag {
    Diag::error("resolve", msg, span)
}

impl Env {
    pub fn eval_term(&self, t: &Term, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
        match t {
            Term::Num(v, _, _) => Ok(EV::Num(*v)),
            Term::Group(e, _) => self.eval(e, locals),
            Term::Call(name, args, sp) => self.call(name, args, locals, *sp),
            Term::Ident(n, sp) => self.lookup(n, locals, *sp),
            Term::Str(s, _) => Ok(EV::Str(s.clone())),
            _ => Err(err("expected a number", t.span())),
        }
    }

    fn lookup(&self, n: &str, locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
        if let Some(v) = locals.get(n) {
            return Ok(v.clone());
        }
        if let Some(v) = self.vars.get(n) {
            return Ok(v.clone());
        }
        match n {
            "pi" => Ok(EV::Num(std::f64::consts::PI)),
            "e" => Ok(EV::Num(std::f64::consts::E)),
            _ => Err(err(&format!("unknown name '{}' in an expression", n), sp)),
        }
    }

    pub fn eval(&self, e: &Expr, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
        match e {
            Expr::Num(v, _) => Ok(EV::Num(*v)),
            Expr::Percent(v, _) => Ok(EV::Num(*v / 100.0)),
            Expr::Str(s, _) => Ok(EV::Str(s.clone())),
            Expr::Ident(n, sp) => self.lookup(n, locals, *sp),
            Expr::Var(_, sp) | Expr::Hash(_, sp) => Err(err("expected a number", *sp)),
            Expr::Call(name, args, sp) => self.call(name, args, locals, *sp),
            Expr::Unary(op, a, sp) => {
                let v = self.eval(a, locals)?;
                let x = v.num().ok_or_else(|| err("expected a number", *sp))?;
                Ok(EV::Num(match op.as_str() {
                    "-" => -x,
                    "!" => {
                        if x == 0.0 {
                            1.0
                        } else {
                            0.0
                        }
                    }
                    _ => x,
                }))
            }
            Expr::Bin(op, a, b, sp) => {
                let x = self.eval(a, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                if op == "&&" {
                    if x == 0.0 {
                        return Ok(EV::Num(0.0));
                    }
                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
                }
                if op == "||" {
                    if x != 0.0 {
                        return Ok(EV::Num(1.0));
                    }
                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
                }
                let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                let b2 = |c: bool| if c { 1.0 } else { 0.0 };
                Ok(EV::Num(match op.as_str() {
                    "+" => x + y,
                    "-" => x - y,
                    "*" => x * y,
                    "/" => x / y,
                    "^" => x.powf(y),
                    "<" => b2(x < y),
                    ">" => b2(x > y),
                    "<=" => b2(x <= y),
                    ">=" => b2(x >= y),
                    "==" => b2(x == y),
                    "!=" => b2(x != y),
                    _ => return Err(err("unknown operator", *sp)),
                }))
            }
            Expr::Ternary(c, a, b, sp) => {
                let cv = self.eval(c, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                if cv != 0.0 {
                    self.eval(a, locals)
                } else {
                    self.eval(b, locals)
                }
            }
            Expr::Tuple(items, _) => {
                let mut out = Vec::new();
                for it in items {
                    out.push(self.eval(it, locals)?);
                }
                Ok(EV::Tuple(out))
            }
            Expr::Block(binds, body, _) => {
                let mut l2 = locals.clone();
                for (n, ex) in binds {
                    let v = self.eval(ex, &l2)?;
                    l2.insert(n.clone(), v);
                }
                self.eval(body, &l2)
            }
        }
    }

    fn call(&self, name: &str, args: &[Expr], locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
        if let Some(f) = self.funcs.get(name) {
            let mut l2 = locals.clone();
            for (i, p) in f.params.iter().enumerate() {
                let v = match args.get(i) {
                    Some(a) => self.eval(a, locals)?,
                    None => EV::Num(0.0),
                };
                l2.insert(p.clone(), v);
            }
            return self.eval_term(&f.body, &l2);
        }
        let mut xs = Vec::new();
        for a in args {
            match self.eval(a, locals)? {
                EV::Num(v) => xs.push(v),
                _ => return Err(err("expected a number", a.span())),
            }
        }
        let a = |i: usize| xs.get(i).copied().unwrap_or(0.0);
        let v = match name {
            "sin" => a(0).sin(),
            "cos" => a(0).cos(),
            "tan" => a(0).tan(),
            "sqrt" => a(0).sqrt(),
            "abs" => a(0).abs(),
            "exp" => a(0).exp(),
            "ln" => a(0).ln(),
            "log" => a(0).log10(),
            "floor" => a(0).floor(),
            "round" => a(0).round(),
            "pow" => a(0).powf(a(1)),
            "min" => xs.iter().cloned().fold(f64::INFINITY, f64::min),
            "max" => xs.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
            "clamp" => a(0).max(a(1)).min(a(2)),
            _ => return Err(err(&format!("unknown function '{}'", name), sp)),
        };
        Ok(EV::Num(v))
    }
}

// Style values: cascade, inheritance, and CSS serialisation.

use crate::ast::{Decl, Expr, Term, Value};
use crate::diag::{Diag, Span};
use crate::eval::{Env, EV};
use crate::util::f4;
use std::collections::HashMap;

// CSS properties in the order they are serialised.
pub const CSS_ORDER: &[&str] = &[
    "fill",
    "stroke",
    "stroke-width",
    "opacity",
    "color",
    "font-family",
    "font-size",
    "font-weight",
    "font-style",
    "text-decoration",
    "text-shadow",
    "stroke-style",
];

pub const INHERITED: &[&str] = &[
    "font-size",
    "font-weight",
    "font-family",
    "font-style",
    "color",
    "letter-spacing",
    "line-spacing",
    "text-transform",
    "text-decoration",
    "text-shadow",
];

pub fn parse_decls(src: &'static str) -> Vec<Decl> {
    let full = format!("{{{}}}", src);
    let lexed = crate::lexer::lex(&full).expect("defaults lex");
    let mut p = crate::parser::Parser::new(&lexed.tokens, &full);
    let (decls, _) = p.parse_style_block().expect("defaults parse");
    decls
}

static DEFAULTS_CACHE: std::sync::OnceLock<HashMap<&'static str, Vec<Decl>>> = std::sync::OnceLock::new();

pub fn type_defaults(name: &str) -> &'static [Decl] {
    let m = DEFAULTS_CACHE.get_or_init(|| {
        let mut m = HashMap::new();
        for t in crate::types::TYPES {
            m.insert(t.name, parse_decls(t.defaults));
        }
        m
    });
    match m.get(name) {
        Some(v) => v,
        None => &[],
    }
}

// --------------------------------------------------------------- values

pub fn single_term(v: &Value) -> Option<&Term> {
    if v.groups.len() == 1 && v.groups[0].len() == 1 {
        Some(&v.groups[0][0])
    } else {
        None
    }
}

pub fn ident_of(v: &Value) -> Option<&str> {
    match single_term(v) {
        Some(Term::Ident(s, _)) => Some(s.as_str()),
        _ => None,
    }
}

pub fn term_num(env: &Env, t: &Term) -> Option<f64> {
    match t {
        Term::Num(v, _, _) => Some(*v),
        Term::Group(e, _) => env.eval(e, &HashMap::new()).ok().and_then(|x| x.num()),
        Term::Call(..) => env.eval_term(t, &HashMap::new()).ok().and_then(|x| x.num()),
        Term::Ident(n, _) => match env.vars.get(n) {
            Some(EV::Num(v)) => Some(*v),
            _ => None,
        },
        _ => None,
    }
}

pub fn value_nums(env: &Env, v: &Value) -> Vec<f64> {
    let mut out = Vec::new();
    for g in &v.groups {
        for t in g {
            if let Some(x) = term_num(env, t) {
                out.push(x);
            }
        }
    }
    out
}

pub fn value_num(env: &Env, v: &Value) -> Option<f64> {
    single_term(v).and_then(|t| term_num(env, t))
}

