pub fn decls_to_map(decls: &[Decl]) -> Vec<(String, Value)> {
    decls.iter().map(|d| (d.name.clone(), d.value.clone())).collect()
}

pub fn build_sheet(doc: &Doc) -> Result<SheetModel, Diag> {
    let mut m = SheetModel::default();
    if let Some(sheet) = &doc.sheet {
        for item in &sheet.items {
            match item {
                SheetItem::Decl(d) => m.root.push(d.clone()),
                SheetItem::Var(d) => m.vars.push(d.clone()),
                SheetItem::Binding(b) => {
                    if let Some(params) = &b.params {
                        m.env.funcs.insert(b.name.clone(), Func { params: params.clone(), body: b.expr.clone() });
                    } else {
                        let v = m.env.eval_term(&b.expr, &HashMap::new())?;
                        m.env.vars.insert(b.name.clone(), v);
                    }
                }
                SheetItem::Rule(r) => {
                    // classify selector
                    if r.selector.len() == 1 {
                        let c = &r.selector[0];
                        if c.bars && c.type_name.as_deref() == Some("-") && c.id.is_none() && c.classes.is_empty() {
                            m.link_rules.extend(r.decls.iter().cloned());
                            continue;
                        }
                        if c.bars && c.id.is_none() && c.classes.is_empty() {
                            if let Some(t) = &c.type_name {
                                m.type_rules.push((t.clone(), r.decls.clone()));
                                continue;
                            }
                        }
                        if !c.bars && c.id.is_none() && c.classes.len() == 1 {
                            m.classes.push(ClassRule { name: c.classes[0].clone(), decls: r.decls.clone(), span: r.span, used: false });
                            continue;
                        }
                        if c.id.is_some() && c.classes.is_empty() {
                            m.id_rules.push((c.id.clone().unwrap(), r.decls.clone()));
                            continue;
                        }
                    }
                    if r.selector.len() == 2 {
                        let a = &r.selector[0];
                        let b = &r.selector[1];
                        if a.id.is_some() && !a.bars && b.bars && b.type_name.as_deref() == Some("-") {
                            m.scoped_link_rules.push((a.id.clone().unwrap(), r.decls.clone()));
                            continue;
                        }
                    }
                }
                SheetItem::Define(d) => {
                    m.defines.push(DefineModel {
                        name: d.name.clone(),
                        base: d.base.clone(),
                        decls: d.decls.clone(),
                        body: d.body.clone(),
                        span: d.span,
                    });
                }
            }
        }
    }
    Ok(m)
}

// The type chain of a (possibly user-defined) type, most-derived first.
pub fn type_chain(sheet: &SheetModel, name: &str) -> Option<(Prim, Vec<String>)> {
    let mut chain = Vec::new();
    let mut cur = name.to_string();
    let mut guard = 0;
    loop {
        guard += 1;
        if guard > 50 {
            return None;
        }
        if let Some(d) = sheet.define(&cur) {
            chain.push(cur.clone());
            cur = d.base.clone();
            continue;
        }
        let t = types::find(&cur)?;
        if t.name == "text" {
            return None;
        }
        chain.push(cur.clone());
        match t.base {
            Some(b) => cur = b.to_string(),
            None => return Some((t.prim, chain)),
        }
    }
}

pub struct Builder<'a> {
    pub sheet: &'a SheetModel,
    pub src: &'a str,
    pub nodes: Vec<Node>,
    pub links: Vec<Link>,
    pub pending_links: Vec<(usize, LinkStmt, usize)>, // (container node, stmt, stmt index)
    pub warnings: Vec<Diag>,
    pub ids: HashMap<(usize, String), usize>,
    pub cap_counter: usize,
    pub stmt_counter: usize,
}

pub fn unknown_type(name: &str, span: Span) -> Diag {
    Diag::error("unknown-type", &format!("unknown type '{}'", name), span)
}

impl<'a> Builder<'a> {
    pub fn new(sheet: &'a SheetModel, src: &'a str) -> Self {
        Builder { sheet, src, nodes: vec![], links: vec![], pending_links: vec![], warnings: vec![], ids: HashMap::new(), cap_counter: 0, stmt_counter: 0 }
    }

    // The id scope children of `p` live in: `p` itself when it has an id, else p's scope.
    pub fn child_scope(&self, p: usize) -> usize {
        if p == 0 || self.nodes[p].id.is_some() {
            p
        } else {
            self.nodes[p].scope
        }
    }

    pub fn add(&mut self, mut n: Node, parent: Option<usize>) -> usize {
        n.parent = parent;
        if let Some(p) = parent {
            n.scope = self.child_scope(p);
        }
        let i = self.nodes.len();
        self.nodes.push(n);
        if let Some(p) = parent {
            self.nodes[p].children.push(i);
        }
        i
    }

    pub fn text_node(&mut self, text: &str, classes: &[String], style: Option<&Vec<Decl>>, span: Span, parent: usize) -> usize {
        let mut n = Node::new(Prim::Text, vec![], span);
        n.text = Some(text.to_string());
        n.classes = classes.to_vec();
        if let Some(s) = style {
            n.inline = s.clone();
        }
        self.add(n, Some(parent))
    }

    pub fn build_stmts(&mut self, stmts: &[Stmt], parent: usize) -> Result<(), Diag> {
        for s in stmts {
            match s {
                Stmt::Node(ns) => {
                    self.build_node(ns, parent)?;
                }
                Stmt::Text(t) => {
                    self.check_classes(&t.classes, t.span)?;
                    if !t.text.is_empty() {
                        self.text_node(&t.text, &t.classes, t.style.as_ref(), t.span, parent);
                    }
                }
                Stmt::Link(l) => {
                    // capsule endpoints are declared in statement order
                    let idx = self.stmt_counter;
                    self.stmt_counter += 1;
                    let mut l2 = l.clone();
                    for g in l2.groups.iter_mut() {
                        for ep in g.iter_mut() {
                            if let Endpoint::Node(ns) = ep {
                                let id = match &ns.id {
                                    Some(id) => id.clone(),
                                    None => {
                                        self.cap_counter += 1;
                                        format!("lini-cap-{}", self.cap_counter)
                                    }
                                };
                                let mut ns2 = (**ns).clone();
                                ns2.id = Some(id.clone());
                                let ni = self.build_node(&ns2, parent)?;
                                if ns.id.is_none() {
                                    self.nodes[ni].auto = false;
                                }
                                *ep = Endpoint::Path(PathRef { parts: vec![id], index: None, anchor: None, span: ns.span });
                            }
                        }
                    }
                    self.pending_links.push((parent, l2, idx));
                }
            }
        }
        Ok(())
    }

    pub fn check_classes(&mut self, classes: &[String], span: Span) -> Result<(), Diag> {
        for c in classes {
            if self.sheet.class(c).is_none() {
                return Err(Diag::error("unknown-class", &format!("unknown class '.{}'", c), span));
            }
        }
        Ok(())
    }

    pub fn build_node(&mut self, ns: &NodeStmt, parent: usize) -> Result<usize, Diag> {
        let tname = match &ns.type_name {
            Some(t) => t.clone(),
            None => "box".to_string(),
        };
        if tname == "link" {
            return Err(Diag::error("resolve", "links are drawn by operators, not the '|link|' type", ns.head_span));
        }
        let (prim, chain) = match type_chain(self.sheet, &tname) {
            Some(x) => x,
            None => return Err(unknown_type(&tname, ns.span)),
        };
        self.check_classes(&ns.classes, ns.span)?;
        let mut n = Node::new(prim, chain.clone(), ns.span);
        n.id = ns.id.clone();
        n.classes = ns.classes.clone();
        n.label = ns.label.as_ref().map(|l| l.0.clone());
        if let Some(st) = &ns.style {
            n.inline = st.clone();
        }
        let scope = self.child_scope(parent);
        if let Some(id) = &ns.id {
            if let Some(&prev) = self.ids.get(&(scope, id.clone())) {
                let (pl, pc) = crate::diag::line_col(self.src, self.nodes[prev].span.start);
                return Err(Diag::error(
                    "duplicate-id",
                    &format!("duplicate id '{}' (previously at {}:{})", id, pl, pc),
                    ns.span,
                ));
            }
        }
        let i = self.add(n, Some(parent));
        if let Some(id) = &ns.id {
            self.ids.insert((scope, id.clone()), i);
        }
        // table family: strings lower into cells (src/table.rs)
        if crate::table::is_table(&chain) {
            crate::table::build(self, ns, i)?;
            return Ok(i);
        }
        // |page|: the sheet chrome (src/page.rs)
        if crate::page::is_page(&chain) {
            crate::page::build(self, ns, i)?;
            return Ok(i);
        }
        // the label
        let is_group = chain.iter().any(|c| c == "group") && !chain.iter().any(|c| c == "table");
        let is_drawing = chain.iter().any(|c| c == "drawing");
        if let Some((label, lspan)) = ns.label.as_ref().filter(|(l, _)| !l.is_empty()) {
            if is_drawing {
                // a drawing's title sits under it
                let cchain = vec!["footnote".to_string(), "caption".to_string(), "block".to_string()];
                let cn = Node::new(Prim::Block, cchain, *lspan);
                let ci = self.add(cn, Some(i));
                self.text_node(label, &[], None, *lspan, ci);
            } else if is_group {
                let cchain = vec!["caption".to_string(), "block".to_string()];
                let mut cn = Node::new(Prim::Block, cchain, *lspan);
                cn.span = *lspan;
                let ci = self.add(cn, Some(i));
                self.text_node(label, &[], None, *lspan, ci);
            } else {
                match prim {
                    Prim::Block | Prim::Oval | Prim::Hex | Prim::Slant | Prim::Cyl | Prim::Diamond | Prim::Sketch => {
                        self.text_node(label, &[], None, *lspan, i);
                    }
                    // an icon's label names its symbol
                    Prim::Icon => self.nodes[i].text = Some(label.clone()),
                    // a line keeps its label (a section plane's letter)
                    Prim::Line => self.nodes[i].text = Some(label.clone()),
                    _ => {}
                }
            }
        }
        // a define's body is materialised per instance
        for t in chain.iter().rev() {
            if let Some(d) = self.sheet.define(t) {
                if let Some(body) = d.body.clone() {
                    self.build_stmts(&body, i)?;
                }
            }
        }
        if let Some(ch) = &ns.children {
            self.build_stmts(ch, i)?;
        }
        Ok(i)
    }
}

impl<'a> Builder<'a> {
    // Dotted id path of a node from the root ("g.c").
    pub fn path_of(&self, i: usize) -> String {
        let mut parts = Vec::new();
        let mut cur = i;
        loop {
            if let Some(id) = &self.nodes[cur].id {
                parts.push(id.clone());
            }
            if cur == 0 {
                break;
            }
            let sc = self.nodes[cur].scope;
            if sc == cur {
                break;
            }
            cur = sc;
        }
        parts.reverse();
        parts.join(".")
    }

    fn scope_name(&self, scope: usize) -> String {
        if scope == 0 {
            "scene root".to_string()
        } else {
            self.path_of(scope)
        }
    }

    pub fn lookup(&self, scope: usize, parts: &[String]) -> Option<usize> {
        let mut cur = scope;
        for p in parts {
            cur = *self.ids.get(&(cur, p.clone()))?;
        }
        Some(cur)
    }

    // First node with this id anywhere below `scope` (depth-first, document order).
    fn find_deep(&self, scope: usize, id: &str) -> Option<usize> {
        let mut stack: Vec<usize> = self.nodes[scope].children.iter().rev().cloned().collect();
        while let Some(n) = stack.pop() {
            if self.nodes[n].id.as_deref() == Some(id) && self.nodes[n].scope != scope {
                return Some(n);
            }
            for &c in self.nodes[n].children.iter().rev() {
                stack.push(c);
            }
        }
        None
    }

    // Resolve one endpoint, auto-creating a bare name as |box#name| "name".
    fn endpoint(&mut self, container: usize, p: &PathRef) -> Result<usize, Diag> {
        let scope = self.child_scope(container);
        if let Some(n) = self.lookup(scope, &p.parts) {
            return Ok(n);
        }
        if p.parts.len() > 1 {
            let msg = if scope == 0 {
                format!("link endpoint '{}' not found at scene root", p.parts.join("."))
            } else {
                format!("link endpoint '{}' not found in '{}'", p.parts.join("."), self.path_of(scope))
            };
            return Err(Diag::error("unknown-endpoint", &msg, p.span));
        }
        let name = p.parts[0].clone();
        if let Some(other) = self.find_deep(scope, &name) {
            let msg = format!(
                "endpoint '{}' auto-created at {} — a node '{}' also exists at '{}'",
                name,
                self.scope_name(scope),
                name,
                self.path_of(other)
            );
            self.warnings.push(Diag::warning("validate", &msg, p.span));
        }
        let chain = vec!["box".to_string(), "block".to_string()];
        let mut n = Node::new(Prim::Block, chain, p.span);
        n.id = Some(name.clone());
        n.auto = true;
        let i = self.add(n, Some(container));
        self.ids.insert((scope, name.clone()), i);
        self.text_node(&name, &[], None, p.span, i);
        Ok(i)
    }

    pub fn resolve_links(&mut self) -> Result<(), Diag> {
        let pending = std::mem::take(&mut self.pending_links);
        for (container, l, idx) in pending {
            for c in &l.classes {
                if self.sheet.class(c).is_none() {
                    return Err(Diag::error("unknown-class", &format!("unknown class '.{}'", c), l.span));
                }
            }
            let mut groups: Vec<Vec<(usize, Option<String>, Option<u32>)>> = Vec::new();
            for g in &l.groups {
                let mut v = Vec::new();
                for ep in g {
                    match ep {
                        Endpoint::Path(p) => {
                            let n = self.endpoint(container, p)?;
                            v.push((n, p.anchor.clone(), p.index));
                        }
                        Endpoint::Node(_) | Endpoint::Text(..) => {}
                    }
                }
                groups.push(v);
            }
            if groups.len() < 2 {
                return Err(Diag::error("chain-too-short", "link requires at least two endpoints", l.span));
            }
            for k in 0..groups.len() - 1 {
                let op = l.ops.get(k).map(|o| o.0.clone()).unwrap_or_default();
                for a in &groups[k] {
                    for b in &groups[k + 1] {
                        self.links.push(Link {
                            from: a.0,
                            to: b.0,
                            op: op.clone(),
                            label: l.label.as_ref().map(|x| x.0.clone()),
                            labels: l.labels.clone().unwrap_or_default(),
                            classes: l.classes.clone(),
                            style: l.style.clone().unwrap_or_default(),
                            from_anchor: a.1.clone(),
                            to_anchor: b.1.clone(),
                            from_index: a.2,
                            to_index: b.2,
                            span: l.span,
                            stmt_index: idx,
                            container,
                        });
                    }
                }
            }
        }
        Ok(())
    }
}

impl<'a> Builder<'a> {
    pub fn unworn_class_warnings(&mut self) {
        for c in &self.sheet.classes {
            let worn = self.nodes.iter().any(|n| n.classes.contains(&c.name))
                || self.links.iter().any(|l| {
                    l.classes.contains(&c.name) || l.labels.iter().any(|s| matches!(s, Stmt::Text(t) if t.classes.contains(&c.name)))
                });
            if !worn {
                self.warnings.push(Diag::warning("class-never-worn", &format!("class '.{}' is never worn", c.name), c.span));
            }
        }
    }
}

// The compile pipeline: scene → styles → layout → routes → SVG.

use crate::ast::*;
use crate::diag::{Diag, Span};
use crate::eval::Env;
use crate::font::Family;
use crate::scene::*;
use crate::style::*;
use crate::types::Prim;
use std::collections::HashMap;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Dir {
    Row,
    Column,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Align {
    Start,
    Center,
    End,
    Stretch,
}

#[derive(Clone, Debug)]
pub struct Computed {
    pub font_size: f64,
    pub font_weight: u32,
    pub family: Family,
    pub letter_spacing: f64,
    pub line_spacing: f64,
    pub text_transform: Option<String>,
    pub padding: [f64; 4], // top right bottom left
    pub gap: (f64, f64),   // (row gap, column gap)
    pub direction: Dir,
    pub align: Align,
    pub justify: Align,
    pub width: Option<f64>,
    pub height: Option<f64>,
    pub max_width: Option<f64>,
    pub stroke_width: f64,
    pub has_stroke: bool,
    pub radius: f64,
    pub pin: Option<String>,
    pub translate: (f64, f64),
    pub rotate: f64,
    pub layout: String,
    pub nowrap: bool,
    pub family_css: Option<String>,
}

impl Default for Computed {
    fn default() -> Self {
        Computed {
            font_size: 15.0,
            font_weight: 500,
            family: Family::Sans,
            letter_spacing: 0.0,
            line_spacing: 0.0,
            text_transform: None,
            padding: [0.0; 4],
            gap: (36.0, 36.0),
            direction: Dir::Row,
            align: Align::Center,
            justify: Align::Center,
            width: None,
            height: None,
            max_width: None,
            stroke_width: 2.0,
            has_stroke: false,
            radius: 0.0,
            pin: None,
            translate: (0.0, 0.0),
            rotate: 0.0,
            layout: "flow".into(),
            nowrap: false,
            family_css: None,
        }
    }
}

pub struct Ctx {
    pub src: String,
    pub file: String,
    pub sheet: SheetModel,
    pub nodes: Vec<Node>,
    pub comp: Vec<Computed>,
    pub links: Vec<Link>,
    pub warnings: Vec<Diag>,
    pub root_font_size: f64,
    // sketch / drawing layout state (src/drawing.rs)
    pub sk: crate::drawing::State,
    // routed links (filled by links::compute after layout)
    pub link_geo: Vec<crate::links::LinkGeo>,
}

pub fn env(ctx: &Ctx) -> &Env {
    &ctx.sheet.env
}

// The cascade for one node: type chain (base first, defaults then user
// rules), classes, id rules, inline. Returns (rule-level props, all props).
pub fn cascade(sheet: &SheetModel, n: &Node) -> (Vec<(String, Value)>, Vec<(String, Value)>) {
    let mut props: Vec<(String, Value)> = Vec::new();
    fn set(props: &mut Vec<(String, Value)>, k: &str, v: &Value) {
        if let Some(e) = props.iter_mut().find(|e| e.0 == k) {
            e.1 = v.clone();
        } else {
            props.push((k.to_string(), v.clone()));
        }
    }
    // table column classes (.lini-align-*, .lini-justify-*) sit below every rule
    for t in n.chain.iter() {
        if let Some((k, v)) = crate::table::pseudo_class(t) {
            set(&mut props, k, &crate::table::pseudo_value(v));
        }
    }
    for t in n.chain.iter().rev() {
        for d in type_defaults(t) {
            set(&mut props, &d.name, &d.value);
        }
        if let Some(df) = sheet.define(t) {
            for d in &df.decls {
                set(&mut props, &d.name, &d.value);
            }
        }
        for d in sheet.type_rule(t) {
            set(&mut props, &d.name, &d.value);
        }
    }
    for c in &n.classes {
        if let Some(cr) = sheet.class(c) {
            for d in &cr.decls {
                set(&mut props, &d.name, &d.value);
            }
        }
    }
    let rule_level = props.clone();
    if let Some(id) = &n.id {
        for (rid, ds) in &sheet.id_rules {
            if rid == id {
                for d in ds {
                    set(&mut props, &d.name, &d.value);
                }
            }
        }
    }
    for d in &n.inline {
        set(&mut props, &d.name, &d.value);
    }
    (rule_level, props)
}

pub fn get<'a>(props: &'a [(String, Value)], k: &str) -> Option<&'a Value> {
    props.iter().find(|e| e.0 == k).map(|e| &e.1)
}

fn parse_align(s: &str) -> Option<Align> {
    match s {
        "start" | "top" | "left" => Some(Align::Start),
        "center" | "middle" => Some(Align::Center),
        "end" | "bottom" | "right" => Some(Align::End),
        "stretch" => Some(Align::Stretch),
        _ => None,
    }
}

pub fn compute(ctx: &mut Ctx) {
    let n = ctx.nodes.len();
    ctx.comp = vec![Computed::default(); n];
    // nodes are created parent-before-child, so a forward pass sees parents first
    for i in 0..n {
        let parent = ctx.nodes[i].parent;
        let pc = parent.map(|p| ctx.comp[p].clone());
        let (_, props) = if i == 0 { (vec![], ctx.nodes[0].inline.iter().map(|d| (d.name.clone(), d.value.clone())).collect()) } else { cascade(&ctx.sheet, &ctx.nodes[i]) };
        let env = &ctx.sheet.env;
        let mut c = Computed::default();
        if let Some(p) = &pc {
            c.font_size = p.font_size;
            c.font_weight = p.font_weight;
            c.family = p.family;
            c.letter_spacing = p.letter_spacing;
            c.line_spacing = p.line_spacing;
            c.text_transform = p.text_transform.clone();
            c.family_css = p.family_css.clone();
        }
        let num = |k: &str| get(&props, k).and_then(|v| value_num(env, v));
        if let Some(v) = num("font-size") {
            c.font_size = v;
        } else if let Some(v) = get(&props, "font-scale") {
            let xs = value_nums(env, v);
            if xs.len() == 2 {
                let base = pc.as_ref().map(|p| p.font_size).unwrap_or(15.0);
                c.font_size = xs[0] * base / xs[1];
            }
        }
        if let Some(v) = get(&props, "font-weight") {
            c.font_weight = weight_num(v);
        }
        if let Some(v) = get(&props, "font-family") {
            c.family = family_of(v);
            c.family_css = Some(font_family_css(v));
        }
        if let Some(v) = num("letter-spacing") {
            c.letter_spacing = v;
        }
        if let Some(v) = num("line-spacing") {
            c.line_spacing = v;
        }
        if let Some(v) = get(&props, "text-transform") {
            c.text_transform = ident_of(v).map(|s| s.to_string());
        }
        if let Some(v) = get(&props, "padding") {
            let xs = value_nums(env, v);
            c.padding = match xs.len() {
                1 => [xs[0]; 4],
                2 => [xs[0], xs[1], xs[0], xs[1]],
                4 => [xs[0], xs[1], xs[2], xs[3]],
                _ => [0.0; 4],
            };
        }
        if let Some(v) = get(&props, "gap") {
            let xs = value_nums(env, v);
            c.gap = match xs.len() {
                1 => (xs[0], xs[0]),
                2 => (xs[0], xs[1]),
                _ => c.gap,
            };
        }
        if let Some(v) = get(&props, "direction") {
            if ident_of(v) == Some("column") {
                c.direction = Dir::Column;
            }
        }
        if let Some(v) = get(&props, "align") {
            if let Some(a) = ident_of(v).and_then(parse_align) {
                c.align = a;
            }
        }
        if let Some(v) = get(&props, "justify") {
            if let Some(a) = ident_of(v).and_then(parse_align) {
                c.justify = a;
            }
        }
        c.width = num("width");
        c.height = num("height");
        c.max_width = num("max-width");
        if let Some(v) = num("stroke-width") {
            c.stroke_width = v;
        }
        if let Some(v) = get(&props, "stroke") {
            c.has_stroke = ident_of(v) != Some("none");
        }
        if let Some(v) = num("radius") {
            c.radius = v;
        }
        if let Some(v) = get(&props, "pin") {
            let mut parts = Vec::new();
            for g in &v.groups {
                for t in g {
                    if let Term::Ident(s, _) = t {
                        parts.push(s.clone());
                    }
                }
            }
            c.pin = Some(parts.join(" "));
        }
        if let Some(v) = get(&props, "translate") {
            let xs = value_nums(env, v);
            if xs.len() == 2 {
                c.translate = (xs[0], xs[1]);
            }
        }
        if let Some(v) = num("rotate") {
            c.rotate = v;
        }
        if let Some(v) = get(&props, "layout") {
            if let Some(s) = ident_of(v) {
                c.layout = s.to_string();
            }
        }
        if let Some(v) = get(&props, "text-wrap") {
            c.nowrap = ident_of(v) == Some("nowrap");
        }
        ctx.nodes[i].props = props.into_iter().collect();
        ctx.comp[i] = c;
    }
}

pub fn root_decls_node(sheet: &SheetModel) -> Node {
    let mut n = Node::new(Prim::Block, vec![], Span::default());
    let defaults = parse_decls("layout: flow; padding: 20; gap: 36; font-size: 15;");
    let mut inline = defaults;
    for d in &sheet.root {
        if let Some(e) = inline.iter_mut().find(|e| e.name == d.name) {
            *e = d.clone();
        } else {
            inline.push(d.clone());
        }
    }
    n.inline = inline;
    n
}
// Compile-time expression evaluation: bindings, functions, math.

use crate::ast::{Expr, Term};
use crate::diag::{Diag, Span};
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum EV {
    Num(f64),
    Tuple(Vec<EV>),
    Str(String),
}

impl EV {
    pub fn num(&self) -> Option<f64> {
        match self {
            EV::Num(v) => Some(*v),
            _ => None,
        }
    }
}

#[derive(Clone, Debug)]
pub struct Func {
    pub params: Vec<String>,
    pub body: Term,
}

#[derive(Default, Clone, Debug)]
pub struct Env {
    pub vars: HashMap<String, EV>,
    pub funcs: HashMap<String, Func>,
}

pub fn err(msg: &str, span: Span) -> Diag {
    Diag::error("resolve", msg, span)
}

impl Env {
    pub fn eval_term(&self, t: &Term, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
        match t {
            Term::Num(v, _, _) => Ok(EV::Num(*v)),
            Term::Group(e, _) => self.eval(e, locals),
            Term::Call(name, args, sp) => self.call(name, args, locals, *sp),
            Term::Ident(n, sp) => self.lookup(n, locals, *sp),
            Term::Str(s, _) => Ok(EV::Str(s.clone())),
            _ => Err(err("expected a number", t.span())),
        }
    }

    fn lookup(&self, n: &str, locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
        if let Some(v) = locals.get(n) {
            return Ok(v.clone());
        }
        if let Some(v) = self.vars.get(n) {
            return Ok(v.clone());
        }
        match n {
            "pi" => Ok(EV::Num(std::f64::consts::PI)),
            "e" => Ok(EV::Num(std::f64::consts::E)),
            _ => Err(err(&format!("unknown name '{}' in an expression", n), sp)),
        }
    }

    pub fn eval(&self, e: &Expr, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
        match e {
            Expr::Num(v, _) => Ok(EV::Num(*v)),
            Expr::Percent(v, _) => Ok(EV::Num(*v / 100.0)),
            Expr::Str(s, _) => Ok(EV::Str(s.clone())),
            Expr::Ident(n, sp) => self.lookup(n, locals, *sp),
            Expr::Var(_, sp) | Expr::Hash(_, sp) => Err(err("expected a number", *sp)),
            Expr::Call(name, args, sp) => self.call(name, args, locals, *sp),
            Expr::Unary(op, a, sp) => {
                let v = self.eval(a, locals)?;
                let x = v.num().ok_or_else(|| err("expected a number", *sp))?;
                Ok(EV::Num(match op.as_str() {
                    "-" => -x,
                    "!" => {
                        if x == 0.0 {
                            1.0
                        } else {
                            0.0
                        }
                    }
                    _ => x,
                }))
            }
            Expr::Bin(op, a, b, sp) => {
                let x = self.eval(a, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                if op == "&&" {
                    if x == 0.0 {
                        return Ok(EV::Num(0.0));
                    }
                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
                }
                if op == "||" {
                    if x != 0.0 {
                        return Ok(EV::Num(1.0));
                    }
                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
                }
                let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                let b2 = |c: bool| if c { 1.0 } else { 0.0 };
                Ok(EV::Num(match op.as_str() {
                    "+" => x + y,
                    "-" => x - y,
                    "*" => x * y,
                    "/" => x / y,
                    "^" => x.powf(y),
                    "<" => b2(x < y),
                    ">" => b2(x > y),
                    "<=" => b2(x <= y),
                    ">=" => b2(x >= y),
                    "==" => b2(x == y),
                    "!=" => b2(x != y),
                    _ => return Err(err("unknown operator", *sp)),
                }))
            }
            Expr::Ternary(c, a, b, sp) => {
                let cv = self.eval(c, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                if cv != 0.0 {
                    self.eval(a, locals)
                } else {
                    self.eval(b, locals)
                }
            }
            Expr::Tuple(items, _) => {
                let mut out = Vec::new();
                for it in items {
                    out.push(self.eval(it, locals)?);
                }
                Ok(EV::Tuple(out))
            }
            Expr::Block(binds, body, _) => {
                let mut l2 = locals.clone();
                for (n, ex) in binds {
                    let v = self.eval(ex, &l2)?;
                    l2.insert(n.clone(), v);
                }
                self.eval(body, &l2)
            }
        }
    }

    fn call(&self, name: &str, args: &[Expr], locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
        if let Some(f) = self.funcs.get(name) {
            let mut l2 = locals.clone();
            for (i, p) in f.params.iter().enumerate() {
                let v = match args.get(i) {
                    Some(a) => self.eval(a, locals)?,
                    None => EV::Num(0.0),
                };
                l2.insert(p.clone(), v);
            }
            return self.eval_term(&f.body, &l2);
        }
        let mut xs = Vec::new();
        for a in args {
            match self.eval(a, locals)? {
                EV::Num(v) => xs.push(v),
                _ => return Err(err("expected a number", a.span())),
            }
        }
        let a = |i: usize| xs.get(i).copied().unwrap_or(0.0);
        let v = match name {
            "sin" => a(0).sin(),
            "cos" => a(0).cos(),
            "tan" => a(0).tan(),
            "sqrt" => a(0).sqrt(),
            "abs" => a(0).abs(),
            "exp" => a(0).exp(),
            "ln" => a(0).ln(),
            "log" => a(0).log10(),
            "floor" => a(0).floor(),
            "round" => a(0).round(),
            "pow" => a(0).powf(a(1)),
            "min" => xs.iter().cloned().fold(f64::INFINITY, f64::min),
            "max" => xs.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
            "clamp" => a(0).max(a(1)).min(a(2)),
            _ => return Err(err(&format!("unknown function '{}'", name), sp)),
        };
        Ok(EV::Num(v))
    }
}

