            if (hasO && oi == 0) continue;
            if (!hasO && oi > 0) continue;
            char stops[4][128];
            for (int k = 0; k < t->n; k++) {
                char *d = stops[k]; const char *f = sfmt[fi];
                while (*f) {
                    if (f[0] == '%' && f[1] == 'c') { strcpy(d, t->c[k]); d += strlen(t->c[k]); f += 2; }
                    else if (f[0] == '%' && f[1] == 'o') { strcpy(d, offs[oi][k]); d += strlen(offs[oi][k]); f += 2; }
                    else *d++ = *f++;
                }
                *d = 0;
            }
            for (int s3 = 0; SEP[s3]; s3++)
            for (int sw = 0; WR[sw][0]; sw++) {
                char st[512]; char *q = st;
                size_t L;
                L = strlen(WR[sw][0]); memcpy(q, WR[sw][0], L); q += L;
                for (int j = 0; j < t->n; j++) { if (j) { L = strlen(SEP[s3]); memcpy(q, SEP[s3], L); q += L; } L = strlen(stops[j]); memcpy(q, stops[j], L); q += L; }
                L = strlen(WR[sw][1]); memcpy(q, WR[sw][1], L); q += L;
                *q = 0;
                for (int ki = 0; K[ki]; ki++)
                for (int ai = 0; ai < na; ai++)
                for (int s1 = 0; SEP[s1]; s1++)
                for (int s2 = 0; SEP[s2]; s2++)
                for (int w = 0; WR[w][0]; w++)
                for (int ord = 0; ord < 6; ord++) {
                    const char *f3[3]; const char *k = K[ki]; const char *a = angles[ai];
                    switch (ord) {
                        case 0: f3[0]=k; f3[1]=a; f3[2]=st; break;
                        case 1: f3[0]=k; f3[1]=st; f3[2]=a; break;
                        case 2: f3[0]=a; f3[1]=k; f3[2]=st; break;
                        case 3: f3[0]=a; f3[1]=st; f3[2]=k; break;
                        case 4: f3[0]=st; f3[1]=k; f3[2]=a; break;
                        default: f3[0]=st; f3[1]=a; f3[2]=k; break;
                    }
                    if ((!*k || !*a) && s2) continue; // only need one separator when a field is empty
                    char *p = buf;
                    #define PUT(s) do { size_t LL = strlen(s); memcpy(p, s, LL); p += LL; } while (0)
                    PUT(WR[w][0]);
                    int first = 1; int si = 0;
                    for (int z = 0; z < 3; z++) {
                        if (!*f3[z]) continue;
                        if (!first) { PUT(si == 0 ? SEP[s1] : SEP[s2]); si++; }
                        PUT(f3[z]); first = 0;
                    }
                    PUT(WR[w][1]);
                    size_t n = p - buf;
                    cnt++;
                    if (h8(buf, n) == t->target) { fwrite("FOUND ", 1, 6, stdout); fwrite(buf, 1, n, stdout); printf(" [%s]\n", t->name); fflush(stdout); }
                }
            }
        }
    }
    fprintf(stderr, "tried %lld\n", cnt);
}

