    prev=list(range(len(b)+1))
    for i in range(1,len(a)+1):
        cur=[i]+[0]*len(b)
        for j in range(1,len(b)+1):
            cost=0 if a[i-1]==b[j-1] else 1
            cur[j]=min(prev[j]+1,cur[j-1]+1,prev[j-1]+cost)
        prev=cur
    return prev[len(b)]
ALPH='abcdefghijklmnopqrstuvwxyz-'
def edits1(w):
    out=set()
    for i in range(len(w)+1):
        for c in ALPH:
            out.add(w[:i]+c+w[i:])
            if i<len(w): out.add(w[:i]+c+w[i+1:])
        if i<len(w): out.add(w[:i]+w[i+1:])
    return out
def tieset(q):
    ds=[(lev(q,p),p) for p in PROPS]
    m=min(d for d,_ in ds)
    if m>2: return m,[]
    return m,[p for d,p in ds if d==m]
pairs=[(a,b) for a,b in itertools.combinations(PROPS,2) if lev(a,b)<=4]
print('pairs',len(pairs),file=sys.stderr)
queries={}
random.seed(1)
for a,b in pairs:
    found=None
    # search strings near a that are equally near b
    cand=set([a]) | edits1(a)
    c2=set()
    for x in list(cand):
        if len(c2)>4000: break
        c2|=edits1(x)
    for q in sorted(cand|c2, key=lambda s:(len(s),s)):
        if q in PROPS or not q or q.startswith('-'): continue
        if lev(q,a)!=lev(q,b) or lev(q,a)>2: continue
        m,ts=tieset(q)
        if sorted(ts)==sorted([a,b]):
            found=q; break
    if found: queries[(a,b)]=found
print('queries',len(queries),file=sys.stderr)
pickle.dump(queries,open('/tmp/core/tiequeries.pkl','wb'))

#!/usr/bin/env python3
import pickle, sys
sys.path.insert(0,'/tmp/core/scripts')
from propprobe_list import PROPS
cons=pickle.load(open('/tmp/core/tiecons.pkl','rb'))
# check for cycles and produce an order; ties broken by alphabetical index to see structure
succ={p:set() for p in PROPS}; indeg={p:0 for p in PROPS}
for w,l in cons:
    if l not in succ[w]:
        succ[w].add(l); indeg[l]+=1
order=[]
avail=sorted([p for p in PROPS if indeg[p]==0], key=PROPS.index)
while avail:
    p=avail.pop(0); order.append(p)
    for q in sorted(succ[p], key=PROPS.index):
        indeg[q]-=1
        if indeg[q]==0: avail.append(q); avail.sort(key=PROPS.index)
print('ordered',len(order),'of',len(PROPS))
if len(order)<len(PROPS):
    print('CYCLE among', [p for p in PROPS if p not in order])
# is it consistent with some simple key? test: alphabetical, reverse alphabetical, length
def check(key,name):
    bad=[(w,l) for w,l in cons if not key(w)<key(l)]
    print(name,'violations',len(bad), bad[:8])
check(lambda p:p,'alpha')
check(lambda p:(-len(p),p),'len desc')
check(lambda p:(len(p),p),'len asc')
check(lambda p:p[::-1],'reverse-string')
print(order)

