from propprobe_list import PROPS
m=pickle.load(open('/tmp/core/matrix_1.pkl','rb'))
types=sorted(set(t for t,p in m))
pref=['box','line','chart','axis','title-block','sketch','icon','image','label','pin','R','J','component','plane','door','pie','slice','bubble','mark','band','area','bars','slant','path','page','note','feature-control','drawing','floorplan','wall','hole','poly']
VALUES=sys.argv[1:] or ['red','1','0','-1','1 2','1 2 3','1, 2','"s"','5%','--x','foo','(1+2)','none','auto','2.5']
def ctx(p):
    for t in pref:
        r=m.get((t,p))
        if r and not (r[0]=='V002'):
            return '|%s|'%t
    return 'link'
base=tempfile.mkdtemp(dir='/tmp/core')
jobs=[]
for p in PROPS:
    c=ctx(p)
    for v in VALUES:
        jobs.append((p,c,v))
def run(job):
    p,c,v=job
    d=os.path.join(base,'%d'%abs(hash(job))); os.makedirs(d,exist_ok=True)
    if c=='link': src='a -> b { %s: %s }\n'%(p,v)
    else: src='%s { %s: %s }\n'%(c,p,v)
    open(d+'/r.lini','w').write(src)
    r=subprocess.run(['/workspace/executable','--json','r.lini'],capture_output=True,cwd=d)
