    ds=j['diagnostics']
    errs=[x for x in ds if x['severity']=='error']
    x=errs[0] if errs else (ds[0] if ds else None)
    if not x: return job,'OK'
    return job,'%s%s [%d..%d] %s'%('' if errs else 'W:',x['code'],x['span']['start'],x['span']['end'],x['message'])
with ThreadPoolExecutor(12) as ex:
