#!/usr/bin/env python3
import pickle, json, sys
sys.path.insert(0,'/tmp/core/scripts')
from propprobe_list import PROPS
m=pickle.load(open('/tmp/core/matrix_1.pkl','rb'))
ch=json.load(open('/tmp/core/chains.json'))
ch['mindmap']=['block',['mindmap','topic','block']]
ch['topic']=['block',['topic','block']]
types=sorted(set(t for t,p in m))
chain={t:ch[t][1] for t in types}
names=sorted(set(n for t in types for n in chain[t]))
cover={n:set(t for t in types if n in chain[t]) for n in names}
res={}
for p in PROPS:
    valid=set(); misuse=False; scene=False
    for t in types:
        r=m[(t,p)]
        if r[0]=='V002' and 'has no meaning' in r[1]: misuse=True
        elif r[0]=='V002' and 'scene config' in r[1]: scene=True
        else: valid.add(t)
    if scene: res[p]='SCENE'; continue
    if not misuse: res[p]='ALL'; continue
    # greedy cover with names whose coverage within valid
    good=[n for n in names if cover[n] and cover[n]<=valid]
    chosen=[]; covered=set()
    for n in sorted(good,key=lambda n:-len(cover[n])):
        if not cover[n]<=covered:
            chosen.append(n); covered|=cover[n]
    # drop redundant
    for n in list(chosen):
        rest=set().union(*[cover[x] for x in chosen if x!=n]) if len(chosen)>1 else set()
        if cover[n]<=rest: chosen.remove(n)
    ok = covered==valid
    res[p]=(sorted(chosen), ok)
    print('%-16s %s %s'%(p, ' '.join(sorted(chosen)), '' if ok else 'INEXACT missing=%s'%sorted(valid-covered)))
json.dump(res,open('/tmp/core/owners.json','w'))

