// The id a bare endpoint most likely meant: within min(2, len − 1) edits,
// nearest first, then alphabetical; a numbered sibling ('c2' for 'c') is
// not a typo.
pub fn near_id<'b>(name: &str, ids: impl Iterator<Item = &'b str>) -> Option<String> {
    let n = name.chars().count();
    let limit = 2.min(n.saturating_sub(1));
    let mut best: Option<(usize, String)> = None;
    for id in ids {
        if id == name {
            continue;
        }
        if let Some(rest) = id.strip_prefix(name) {
            if !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit()) {
                continue;
            }
        }
        let d = crate::util::levenshtein(name, id);
        if d > limit {
            continue;
        }
        let key = (d, id.to_string());
        if best.as_ref().map(|b| key < *b).unwrap_or(true) {
            best = Some(key);
        }
    }
    best.map(|b| b.1)
}

// ------------------------------------------------------------------ layout values

fn node_err(msg: &str, span: Span) -> Diag {
    Diag::error("layout", msg, span)
}

// A layout attribute's numbers: "expected a number or tuple, got …".
fn layout_nums(v: &Value, env: &crate::eval::Env) -> Result<Vec<f64>, String> {
    let mut out = Vec::new();
    let terms: Vec<&Term> = v.groups.iter().flat_map(|g| g.iter()).collect();
    for (k, t) in terms.iter().enumerate() {
        let what = match t {
            Term::Num(x, _, _) => {
                out.push(*x);
                continue;
            }
            Term::Group(..) | Term::Call(..) => match crate::style::term_num(env, t) {
                Some(x) => {
                    out.push(x);
                    continue;
                }
                None => "tuple",
            },
            Term::Ident(..) => "identifier",
            Term::Str(..) => "string",
            Term::Hash(..) => "colour",
            Term::Var(n, _) => {
                return Err(format!("var(--lini-{}) is a visual variable; layout attrs require a number or tuple", n));
            }
            _ => "value",
        };
        if what == "tuple" {
            continue;
        }
        return Err(if k == 0 {
            format!("expected a number or tuple, got {}", what)
        } else {
            format!("expected a number, got {}", what)
        });
    }
    Ok(out)
}

// Layout attributes read while measuring (children before parents), then
// pins: padding takes 1, 2 or 4 numbers, translate two, scale is positive.
pub fn layout_values(ctx: &crate::compile::Ctx) -> Result<(), Diag> {
    fn post(ctx: &crate::compile::Ctx, i: usize) -> Result<(), Diag> {
        for &c in &ctx.nodes[i].children {
            post(ctx, c)?;
        }
        if i == 0 {
            return Ok(());
        }
        let n = &ctx.nodes[i];
        let env = &ctx.sheet.env;
        if let Some(v) = n.props.get("padding") {
            let xs = layout_nums(v, env).map_err(|m| node_err(&m, n.span))?;
            if !matches!(xs.len(), 1 | 2 | 4) {
                return Err(node_err(&format!("expected 1, 2, or 4 values, got {}", xs.len()), n.span));
            }
        }
        if let Some(v) = n.props.get("translate") {
            layout_nums(v, env).map_err(|m| node_err(&m, n.span))?;
        }
        if let Some(v) = n.props.get("scale") {
            match crate::style::value_num(env, v) {
                Some(x) if x > 0.0 => {}
                _ => return Err(node_err("'scale' must be > 0", n.span)),
            }
        }
        Ok(())
    }
    fn pins(ctx: &crate::compile::Ctx, i: usize) -> Result<(), Diag> {
        let n = &ctx.nodes[i];
        if i != 0 {
            if let Some(v) = n.props.get("pin") {
                let words: Vec<&str> = v
                    .groups
                    .iter()
                    .flat_map(|g| g.iter())
                    .map(|t| match t {
                        Term::Ident(s, _) => s.as_str(),
                        _ => "?",
                    })
                    .collect();
                let ok = match words.as_slice() {
                    ["none"] | ["center"] | ["top"] | ["bottom"] | ["left"] | ["right"] => true,
                    [a, b] => {
                        let v = |x: &str| x == "top" || x == "bottom";
                        let h = |x: &str| x == "left" || x == "right";
                        (v(a) && h(b)) || (h(a) && v(b))
                    }
                    _ => false,
                };
                if !ok {
                    return Err(node_err(
                        "'pin' expects none, center, an edge (top/bottom/left/right), or a corner (e.g. 'top right')",
                        n.span,
                    ));
                }
            }
        }
        for &c in &n.children {
            pins(ctx, c)?;
        }
        Ok(())
    }
    post(ctx, 0)?;
    pins(ctx, 0)
}

