        for (rid, ds) in &sheet.id_rules {
            if rid == id {
                out.extend(ds.iter().map(|d| (d.name.clone(), d.value.clone())));
            }
        }
    }
    out.extend(n.inline.iter().map(|d| (d.name.clone(), d.value.clone())));
    out
}""")
