STY=['font-weight: bold','font-weight: 600','font-weight: normal','font-size: 20','font-size: 11.5','font-style: italic','text-decoration: underline','text-decoration: line-through','letter-spacing: 2','line-spacing: 4','text-transform: uppercase','font-family: monospace','font-family: "Fira Code"','color: --teal-ink','color: red','opacity: 0.5','fill: gradient(--sky, --purple)','fill: --amber-wash','stroke: --rose','shadow: 2 3 4','text-shadow: 1 1 red','max-width: 60']
TYPES=['box','oval','rect','hex','diamond','cyl','slant','group','badge']
def word(): return random.choice(WORDS)
def sty(n): return '; '.join(random.sample(STY,n))
out=[]
for k in range(400):
    shape=random.randrange(6)
    if shape==0:
        out.append('|%s| "%s" { %s }'%(random.choice(TYPES), word(), sty(random.randint(0,3))))
    elif shape==1:
        out.append('|box#a| "%s" { %s }\n|box#b| "%s"\na -> b "%s" { %s }'%(word(), sty(1), word(), word(), sty(random.randint(0,2))))
    elif shape==2:
        out.append('|group| "%s" { %s } [ |box| "%s" { %s }; "%s" { %s } ]'%(word(), sty(1), word(), sty(1), word(), sty(1)))
    elif shape==3:
        out.append('{ font-size: %d }\n"%s" { %s }\n|box| "%s"'%(random.choice([11,13,15,18]), word(), sty(2), word()))
    elif shape==4:
        out.append('{ .k { %s } }\n|box| "%s" .k\n"%s" .k'%(sty(2), word(), word()))
    else:
        out.append('|table| { columns: auto, auto } [ "%s" "%s"; "%s" "%s" ]'%(word(), word(), word(), word()))
print('\n----\n'.join(out))

#!/usr/bin/env python3
# bulkmode.py "args" SNIPFILE : for snippets that match in default mode, compare in the given mode
import subprocess, sys, tempfile, os
from concurrent.futures import ThreadPoolExecutor
args=sys.argv[1].split(); src=open(sys.argv[2]).read()
mine='/tmp/bin-core/executable'
snips=[s.strip('\n') for s in src.split('\n----\n') if s.strip()]
base=tempfile.mkdtemp(dir='/tmp/core')
def same(d, a):
    o=subprocess.run(['/workspace/executable']+a+['r_in.lini'],capture_output=True,cwd=d)
    m=subprocess.run([mine]+a+['r_in.lini'],capture_output=True,cwd=d,timeout=30)
    return (o.stdout==m.stdout and o.stderr==m.stderr and o.returncode==m.returncode), o, m
def run(k):
    s=snips[k]; d=os.path.join(base,str(k)); os.makedirs(d)
    open(d+'/r_in.lini','w').write(s+'\n')
    ok,_,_=same(d,[])
    if not ok: return ('skip',None)
    ok,o,m=same(d,args)
    if ok: return ('ok',None)
    ol=o.stdout.decode().split('\n'); ml=m.stdout.decode().split('\n')
    for i in range(max(len(ol),len(ml))):
        a=ol[i] if i<len(ol) else ''; b=ml[i] if i<len(ml) else ''
        if a!=b: return ('bad',(s,'L%d\n    O %s\n    M %s'%(i+1,a[:200],b[:200]), o.stderr.decode()[:200], m.stderr.decode()[:200]))
    return ('bad',(s,'stderr/exit',o.stderr.decode()[:300],m.stderr.decode()[:300]))
with ThreadPoolExecutor(12) as ex:
    res=list(ex.map(run,range(len(snips))))
n_ok=sum(1 for r in res if r[0]=='ok'); n_skip=sum(1 for r in res if r[0]=='skip')
for r in res:
    if r[0]=='bad':
        s,w,oe,me=r[1]
        print('### '+s.replace('\n','⏎')[:160]); print('    '+w)
        if oe!=me: print('    ERR O %r\n    ERR M %r'%(oe,me))
print('OK %d / %d (skipped %d failing in default)'%(n_ok,len(snips)-n_skip,n_skip))

