1	// Scoped (descendant) rules: `|box| .c { … }`, `.a .b { … }`, `#a |oval| { … }`,
2	// `|group| |box| { … }`.
3	//
4	// A rule whose selector has two or more compounds applies to a node matching
5	// its last compound inside ancestors matching the rest, in order. Between two
6	// plain types (`|A| |B|`) it is written to the stylesheet as `.lini-A
7	// .lini-B`; any other shape resolves onto each matching node's inline style.
8	// In the cascade a scoped rule sits after the type rules and before classes.
9	
10	use crate::ast::{Compound, Decl, Term, Value};
11	use crate::compile::Ctx;
12	use crate::diag::Diag;
13	use crate::scene::{Node, SheetModel};
14	
15	// Is this selector a plain two-type descendant (emitted as CSS)?
16	pub fn is_css(sel: &[Compound]) -> bool {
17	    sel.len() == 2 && sel.iter().all(|c| c.bars && c.id.is_none() && c.classes.is_empty() && c.type_name.as_deref() != Some("-"))
18	}
19	
20	fn compound_matches(c: &Compound, n: &Node) -> bool {
21	    if let Some(t) = &c.type_name {
22	        if !n.is(t) {
23	            return false;
24	        }
25	    }
26	    if let Some(id) = &c.id {
27	        if n.id.as_deref() != Some(id.as_str()) {
28	            return false;
29	        }
30	    }
31	    c.classes.iter().all(|cl| n.classes.contains(cl))
32	}
33	
34	// Do the compounds match ancestors from `from` outwards, innermost last?
35	fn within(scope: &[Compound], nodes: &[Node], from: Option<usize>) -> bool {
36	    let mut k = scope.len();
37	    let mut cur = from;
38	    while k > 0 {
39	        k -= 1;
40	        loop {
41	            let p = match cur {
42	                Some(p) if p != 0 => p,
43	                _ => return false,
44	            };
45	            cur = nodes[p].parent;
46	            if compound_matches(&scope[k], &nodes[p]) {
47	                break;
48	            }
49	        }
50	    }
51	    true
52	}
53	
54	// Does node `i` match the selector (last compound on it, the rest on its
55	// ancestors)?
56	fn matches(sel: &[Compound], nodes: &[Node], i: usize) -> bool {
57	    let (last, scope) = sel.split_last().unwrap();
58	    compound_matches(last, &nodes[i]) && within(scope, nodes, nodes[i].parent)
59	}
60	
61	// A link's scoped rules (`|box| |-| { … }`, `#g |-| { … }`): those whose
62	// leading compounds match its container and the container's ancestors.
63	pub fn link_decls(ctx: &Ctx, l: &crate::scene::Link) -> Vec<(String, Value)> {
64	    let mut out: Vec<(String, Value)> = Vec::new();
65	    for (scope, ds) in &ctx.sheet.scoped_link_rules {
66	        if within(scope, &ctx.nodes, Some(l.container)) {
67	            for d in ds {
68	                out.retain(|e| e.0 != d.name);
69	                out.push((d.name.clone(), d.value.clone()));
