76	// What of them rides inline: whatever the link's classes leave alone.
77	pub fn link_inline(ctx: &Ctx, l: &crate::scene::Link, scoped: &[(String, Value)]) -> Vec<(String, Value)> {
78	    let by_class = |k: &str| l.classes.iter().any(|c| ctx.sheet.class(c).map_or(false, |cr| cr.decls.iter().any(|d| d.name == k)));
