82	// The scoped rules that reach node `i`, in source order: (decls, is_css).
83	pub fn matching<'a>(sheet: &'a SheetModel, nodes: &[Node], i: usize) -> Vec<(&'a [Decl], bool)> {
84	    if i == 0 || nodes[i].prim == crate::types::Prim::Text {
85	        return vec![];
86	    }
87	    sheet
88	        .scoped_rules
89	        .iter()
90	        .filter(|(sel, _, _)| matches(sel, nodes, i))
91	        .map(|(sel, decls, _)| (decls.as_slice(), is_css(sel)))
92	        .collect()
93	}
