95	// Their declarations as cascade entries.
96	pub fn decls(sheet: &SheetModel, nodes: &[Node], i: usize) -> Vec<(String, Value)> {
97	    let mut out = Vec::new();
98	    for (ds, _) in matching(sheet, nodes, i) {
99	        out.extend(ds.iter().map(|d| (d.name.clone(), d.value.clone())));
100	    }
101	    out
