104	// Inline-style adjustments for a node a scoped rule reaches. The stylesheet
105	// (`rule_props`) gains the plain-type descendant rules, which outrank classes
106	// there; the node's own declarations (`own`) gain what the cascade wants for
107	// every property a scoped rule touches (a class outranks them all). What
108	// the stylesheet already shows is dropped later.
109	pub fn adjust_inline(ctx: &Ctx, i: usize, rule_props: &mut Vec<(String, Value)>, own: &mut Vec<(String, Value)>) {
110	    let found = matching(&ctx.sheet, &ctx.nodes, i);
111	    if found.is_empty() {
112	        return;
113	    }
114	    let set = |v: &mut Vec<(String, Value)>, k: &str, val: &Value| {
115	        v.retain(|e| e.0 != k);
116	        v.push((k.to_string(), val.clone()));
117	    };
118	    let mut touched: Vec<(String, Value)> = Vec::new();
119	    for (ds, css) in found {
120	        for d in ds {
121	            if css {
122	                if is_gradient(&d.value) {
123	                    // the rule shows the gradient's text; its paint rides inline
124	                    rule_props.retain(|e| e.0 != d.name);
125	                } else {
126	                    set(rule_props, &d.name, &d.value);
127	                }
128	            }
129	            set(&mut touched, &d.name, &d.value);
130	        }
131	    }
132	    let n = &ctx.nodes[i];
133	    let mut class_vals: Vec<(String, Value)> = Vec::new();
134	    for c in &n.classes {
135	        if let Some(cr) = ctx.sheet.class(c) {
136	            for d in &cr.decls {
137	                set(&mut class_vals, &d.name, &d.value);
138	            }
139	        }
140	    }
141	    for (k, v) in touched {
142	        let want = class_vals.iter().find(|e| e.0 == k).map(|e| e.1.clone()).unwrap_or(v);
143	        set(own, &k, &want);
144	    }
145	}
