147	// The stroke dasharray the stylesheet shows a node: each rule writes its
148	// own from its own stroke width (else 0), and the last rule in CSS order
149	// that sets a stroke style wins (descendant rules, then classes in sheet
150	// order); `None` leaves the type's.
151	pub fn shown_dash(ctx: &Ctx, i: usize) -> Option<String> {
152	    let mut shown = None;
153	    for (ds, css) in matching(&ctx.sheet, &ctx.nodes, i) {
154	        if css {
155	            if let Some(d) = rule_dash(ctx, ds) {
156	                shown = Some(d);
157	            }
158	        }
159	    }
160	    shown.or_else(|| class_dash(ctx, &ctx.nodes[i].classes))
161	}
162	
163	// (a rule's own dashes, when it sets a stroke style)
164	fn rule_dash(ctx: &Ctx, ds: &[Decl]) -> Option<String> {
165	    let env = &ctx.sheet.env;
166	    let st = ds.iter().rev().find(|d| d.name == "stroke-style")?;
167	    let sw = ds.iter().rev().find(|d| d.name == "stroke-width").and_then(|d| crate::style::value_num(env, &d.value)).unwrap_or(0.0);
168	    Some(crate::style::ident_of(&st.value).and_then(|s| crate::style::dasharray(s, sw)).unwrap_or_else(|| "none".to_string()))
169	}
170	
171	// The dashes the worn classes show (the last in sheet order that sets a
172	// stroke style).
173	pub fn class_dash(ctx: &Ctx, classes: &[String]) -> Option<String> {
174	    let mut shown = None;
175	    for c in &ctx.sheet.classes {
176	        if classes.contains(&c.name) {
177	            if let Some(d) = rule_dash(ctx, &c.decls) {
178	                shown = Some(d);
179	            }
180	        }
181	    }
182	    shown
183	}
