189	// The plain-type descendant rules whose types are both drawn, as
190	// stylesheet slots. A gradient is written as its text (the nodes it reaches
191	// carry the paint server inline).
192	pub fn css_rules(ctx: &Ctx, used_types: &[String], vars: &mut Vec<String>) -> Result<Vec<(String, String)>, Diag> {
193	    let mut slots = Vec::new();
194	    for (k, (sel, decls, _)) in ctx.sheet.scoped_rules.iter().enumerate() {
195	        if !is_css(sel) {
196	            continue;
197	        }
198	        let (a, b) = (sel[0].type_name.clone().unwrap_or_default(), sel[1].type_name.clone().unwrap_or_default());
199	        if !used_types.contains(&a) || !used_types.contains(&b) {
200	            continue;
201	        }
202	        let mut props: Vec<(String, Value)> = Vec::new();
203	        for d in decls {
204	            props.retain(|e| e.0 != d.name);
205	            props.push((d.name.clone(), d.value.clone()));
206	        }
207	        let plain: Vec<(String, Value)> = props.iter().filter(|(_, v)| !is_gradient(v)).cloned().collect();
208	        let mut ds = crate::render::css_decls(ctx, &plain, vars, 0.0, false)?;
209	        for (name, v) in props.iter().filter(|(_, v)| is_gradient(v)) {
210	            ds.push((name.clone(), crate::paint::value_raw(v, vars)));
211	        }
212	        let rank = |k: &str| crate::style::CSS_ORDER.iter().position(|x| *x == k).unwrap_or(99);
213	        ds.sort_by_key(|(k, _)| rank(k));
214	        if !ds.is_empty() {
215	            let body = ds.iter().map(|(k, v)| format!("{}: {}", k, v)).collect::<Vec<_>>().join("; ");
216	            slots.push((format!("@scoped:{:04}", k), format!(".lini-{} .lini-{} {{ {}; }}", a, b, body)));
217	        }
218	    }
219	    Ok(slots)
220	}
