// The id a bare endpoint most likely meant: within min(2, len − 1) edits,
// nearest first, then alphabetical; a numbered sibling ('c2' for 'c') is
// not a typo.
pub fn near_id<'b>(name: &str, ids: impl Iterator<Item = &'b str>) -> Option<String> {
    let n = name.chars().count();
    let limit = 2.min(n.saturating_sub(1));
    let mut best: Option<(usize, String)> = None;
    for id in ids {
        if id == name {
            continue;
        }
        if let Some(rest) = id.strip_prefix(name) {
            if !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit()) {
                continue;
            }
        }
        let d = crate::util::levenshtein(name, id);
        if d > limit {
            continue;
        }
        let key = (d, id.to_string());
        if best.as_ref().map(|b| key < *b).unwrap_or(true) {
            best = Some(key);
        }
    }
    best.map(|b| b.1)
}

