import subprocess, sys, tempfile
tpl=sys.argv[1]; lo=float(sys.argv[2]); hi=float(sys.argv[3]); step=float(sys.argv[4]) if len(sys.argv)>4 else 0.25
binp=sys.argv[5] if len(sys.argv)>5 else '/workspace/executable'
