ea=err(a); eb=err(b)
if ea[0] or not eb[0]:
    print('not bracketing', ea, eb); sys.exit()
while b-a>step:
    m=round((a+b)/2/step)*step
    if m<=a or m>=b: break
    if err(m)[0]: b=m
    else: a=m
print('ok at %g, error at %g'%(a,b), err(b)[1][:120])

