fn write_out(opts: &Options, text: &str) -> Result<(), String> {
    match &opts.output {
        Some(path) => std::fs::write(path, text.as_bytes()).map_err(|e| format!("error: write {}: {}", path, e)),
        None => {
            let mut so = std::io::stdout();
            let _ = so.write_all(text.as_bytes());
            Ok(())
        }
    }
}

