    // max-width overflows met measuring: (the box, the error), children first
    static OVERFLOWS: std::cell::RefCell<Vec<(usize, crate::diag::Diag)>> = const { std::cell::RefCell::new(Vec::new()) };
}

// The first error measuring met (the pipeline stops on it).
pub fn take_error() -> Option<crate::diag::Diag> {
    OVERFLOWS.with(|e| std::mem::take(&mut *e.borrow_mut())).into_iter().next().map(|(_, d)| d)
}

// Every max-width overflow, measuring the scene as it stands (used to order
// them among the layout-value errors, which the layout pass meets on the way).
pub fn overflows(ctx: &mut Ctx) -> Vec<(usize, crate::diag::Diag)> {
    crate::page::scale_units(ctx);
    crate::drawing::prepare(ctx);
    measure(ctx, 0, None);
    OVERFLOWS.with(|e| std::mem::take(&mut *e.borrow_mut()))
}

// Does box `i`'s max-width bound its children (flow-like layouts only:
// other engines place their children themselves, a tree's topics too)?
pub fn max_width_bounds(ctx: &Ctx, i: usize) -> bool {
    if i == 0 || ctx.comp[i].max_width.is_none() {
        return false;
    }
    let engine = |k: usize| matches!(ctx.comp[k].layout.as_str(), "sequence" | "tree" | "drawing" | "floorplan" | "schematic" | "chart" | "pie");
    let mut cur = Some(i);
    while let Some(k) = cur {
        if engine(k) || ctx.nodes[k].is("topic") {
            return false;
        }
        cur = ctx.nodes[k].parent;
    }
    true
}

// A box's max-width wraps text only: a child of any other kind (pinned ones
// aside) whose natural width overflows the room it leaves (padding and
// stroke-width cleared) is an error. Every child's subtree reports first.
fn check_max_width(ctx: &mut Ctx, i: usize) {
    if !max_width_bounds(ctx, i) || OVERFLOWS.with(|e| e.borrow().iter().any(|(k, _)| *k == i)) {
        return;
    }
    let c = ctx.comp[i].clone();
