# gengrad.py N SEED : random documents using gradients in many places
import random, sys
n=int(sys.argv[1]); random.seed(int(sys.argv[2]))
cols=['red','blue','--sky','--teal','--rose','#123','#a0b0c0','oklch(0.6 0.1 200)','rgb(10, 20, 30)','hsl(200, 50%, 40%)','--mine','white','--amber']
def grad():
    k=random.randint(2,4)
    stops=', '.join(random.choice(cols) for _ in range(k))
    r=random.random()
    if r<0.5: return 'gradient(%s)'%stops
    if r<0.8: return 'linear-gradient(%s, %s)'%(random.choice(['0','45','90','135','180','-30','400','(10 * 3)']),stops)
    return 'radial-gradient(%s)'%stops
def paint():
    return grad() if random.random()<0.6 else random.choice(cols)
def decls(link=False):
    ks=random.sample(['fill','stroke','color','shadow','opacity'], random.randint(1,3))
    out=[]
    for k in ks:
        if k=='fill' and not link: out.append('fill: %s'%paint())
        elif k=='stroke': out.append('stroke: %s'%paint())
        elif k=='color': out.append('color: %s'%random.choice(cols))
        elif k=='shadow' and not link: out.append('shadow: %s'%random.choice(['2 3 4','1 1 2 --rose','0 4 8 rgb(0, 0, 0)','3']))
        elif k=='opacity': out.append('opacity: %s'%random.choice(['0.5','1','0.25']))
    return '; '.join(out) if out else 'fill: red'
out=[]
for _ in range(n):
    lines=['{']
    if random.random()<0.5: lines.append('  --mine: %s'%random.choice(['#345','light-dark(#111, #eee)','teal','oklch(0.5 0.2 30)']))
    if random.random()<0.3: lines.append('  fill: %s'%paint())
    if random.random()<0.5: lines.append('  .c { %s }'%decls())
    if random.random()<0.4: lines.append('  |-| { %s }'%decls(True))
    if random.random()<0.4: lines.append('  |oval| { %s }'%decls())
    if random.random()<0.3: lines.append('  .k { %s }'%decls(True))
    lines.append('}')
    body=[]
    for i in range(random.randint(1,3)):
        t=random.choice(['box','oval','box'])
        cls=' .c' if random.random()<0.4 else ''
        st=' { %s }'%decls() if random.random()<0.6 else ''
        body.append('|%s#n%d| "n%d"%s%s'%(t,i,i,cls,st))
    if len(body)>1 and random.random()<0.7:
        lk=' .k' if random.random()<0.4 else ''
        st=' { %s }'%decls(True) if random.random()<0.5 else ''
        body.append('n0 -> n1 "go"%s%s'%(lk,st))
    src='\n'.join(lines)+'\n'+'\n'.join(body)
    if src.startswith('{\n}'): src=src[3:].lstrip('\n')
    out.append(src)
print('\n----\n'.join(out))

