pub fn resolve(doc: &Doc, sheet: &SheetModel) -> Result<(), Diag> {
    let r = R { sheet };
    let used = used_types(doc, sheet);
    let root_layout = sheet
        .root
        .iter()
        .rev()
        .find(|d| d.name == "layout")
        .and_then(|d| crate::style::ident_of(&d.value))
        .unwrap_or("flow")
        .to_string();
    if let Some(sh) = &doc.sheet {
        for item in &sh.items {
            match item {
                SheetItem::Decl(d) => r.decl(d, None)?,
                // a variable's value resolves where it is declared
                SheetItem::Var(d) => r.value_terms("", &d.value).map_err(|(m, fam)| Diag::error(fam, &m, d.span))?,
                SheetItem::Rule(rl) => {
                    // a type's rule resolves only when that type is drawn
                    let c = &rl.selector[0];
                    if rl.selector.len() == 1 && c.bars && c.id.is_none() && c.classes.is_empty() {
                        if let Some(t) = &c.type_name {
                            if t != "-" && !used.contains(t) {
                                continue;
                            }
                        }
                    }
                    for d in &rl.decls {
                        r.decl(d, None)?;
                    }
                }
                SheetItem::Define(df) => {
                    if !used.contains(&df.name) {
                        continue;
                    }
                    for d in &df.decls {
                        r.decl(d, None)?;
                    }
                }
                _ => {}
            }
        }
    }
    let _ = root_layout;
    Ok(())
}

