bad_v=['colr: red','fit: 1','density: 2','opacity: 5','width: 5%','fill: nope','stroke-style: wavy']
good=['fill: red','stroke: --sky','width: 40','padding: 5','font-size: 12']
def style():
    out=[]
    for _ in range(random.randint(0,3)):
        r=random.random()
        if r<0.25: out.append(random.choice(['fill','stroke','width','padding'])+': '+random.choice(bad_r))
        elif r<0.5: out.append(random.choice(bad_v))
        else: out.append(random.choice(good))
