    lbl=' "x%d"'%i if random.random()<0.7 else ''
    cls=' .%s'%random.choice(['c','d','zz']) if random.random()<0.3 else ''
    s='|%s%s|%s%s%s'%(t,idp,lbl,cls,style())
    if depth<2 and random.random()<0.3:
