#!/usr/bin/env python3
# firstdiffs.py SNIPFILE [args] : for failing snippets, bucket by a normalised first differing line
import subprocess, sys, re, difflib, os, tempfile
from collections import Counter
from concurrent.futures import ThreadPoolExecutor
src=open(sys.argv[1]).read().split('\n----\n')
args=sys.argv[2].split() if len(sys.argv)>2 else []
base=tempfile.mkdtemp(dir='/tmp/core')
mask=lambda x: re.sub(r'lini-scope-[0-9a-f]+','S',x)
def run(k):
    s=src[k]
    d=os.path.join(base,str(k)); os.makedirs(d)
    open(d+'/r.lini','w').write(s+'\n')
    o=subprocess.run(['/workspace/executable']+args+['r.lini'],capture_output=True,cwd=d,text=True)
    m=subprocess.run(['/tmp/bin-core/executable']+args+['r.lini'],capture_output=True,cwd=d,text=True)
    if o.stdout==m.stdout and o.stderr==m.stderr and o.returncode==m.returncode: return None
    if o.stderr!=m.stderr:
        return ('ERR', s, o.stderr.strip()[:150]+' || '+m.stderr.strip()[:150])
    ol=mask(o.stdout).split('\n'); ml=mask(m.stdout).split('\n')
    for i,(a,b) in enumerate(zip(ol,ml)):
        if a!=b:
            if i==0:
                # viewBox only: find the next difference
                for j in range(1,min(len(ol),len(ml))):
                    if ol[j]!=ml[j] and 'scope' not in ol[j]:
                        a,b=ol[j],ml[j]; break
            return ('DIFF', s, a.strip()[:200]+'\n      '+b.strip()[:200])
    return ('LEN', s, '')
with ThreadPoolExecutor(8) as ex:
    res=[r for r in ex.map(run, range(len(src))) if r]
def key(r):
    t=r[2].split('\n')[0]
    t=re.sub(r'-?\d+(\.\d+)?','N',t)
    return t[:90]
c=Counter(key(r) for r in res)
ex={}
for r in res: ex.setdefault(key(r), r)
for k,v in c.most_common(30):
    r=ex[k]
    print('%4d %s'%(v,k))
    print('      '+r[1].replace('\n','⏎')[:300])
    print('      '+r[2][:400])

