pub fn place_pinned(ctx: &mut Ctx, parent: usize, i: usize) {
    let pin = ctx.comp[i].pin.clone().unwrap_or_default();
    // a parent sized both ways pins to the size it was given, grown or not;
    // one with nothing in its flow pins to its padding box
    let pc = &ctx.comp[parent];
    let flowless = ctx.nodes[parent].children.iter().all(|&k| ctx.comp[k].pin.is_some());
    let (w, h) = (ctx.nodes[parent].w, ctx.nodes[parent].h);
    let (pw, ph) = match (pc.width, pc.height) {
        (Some(fw), Some(fh)) => (fw, fh),
        // (a size its parent stretched it to still counts)
        (fw, fh) if flowless => (
            if fw == Some(w) { pc.padding[1] + pc.padding[3] } else { w },
            if fh == Some(h) { pc.padding[0] + pc.padding[2] } else { h },
        ),
        _ => (w, h),
    };
    let (cw, chh) = outer(ctx, i);
    let words: Vec<&str> = pin.split_whitespace().collect();
    let mut x = 0.0;
    let mut y = 0.0;
    for w in &words {
        match *w {
            "top" => y = -ph / 2.0 + chh / 2.0,
            "bottom" => y = ph / 2.0 - chh / 2.0,
            "left" => x = -pw / 2.0 + cw / 2.0,
            "right" => x = pw / 2.0 - cw / 2.0,
            _ => {}
        }
    }
    ctx.nodes[i].x = x;
    ctx.nodes[i].y = y;
}

